window.DK_TERIM_DIZIN=window.DK_TERIM_DIZIN||{};DK_TERIM_DIZIN["mto323"]={"v":"77bfcbb985","terim":[{"id":"absorbing-aerosol","tr":"Soğurucu aerosol","en":"absorbing aerosol","kisa":"","tur":"kavram","es":["soğuran aerosol","absorbing particles"],"tanim":["Güneş ışınımını belirgin biçimde soğuran ve tek saçılma albedosu (ω) 1'den küçük olan aerosol türüdür.","İs (siyah karbon), kahverengi karbon ve mineral toz bu grupta yer alır.","Bulunduğu atmosfer tabakasını ısıtırken yeryüzüne ulaşan güneş ışığını azaltır ve yarı doğrudan etkiyle bulutları buharlaştırabilir."],"tanim_en":"An aerosol type that significantly absorbs solar radiation and has a single-scattering albedo notably below unity.","bag":{"kavram":["aerosol-dogrudan"],"soru":["S25"],"hesap":[]}},{"id":"ammonia","tr":"Amonyak","en":"Ammonia","kisa":"NH₃","tur":"kavram","es":["amonyak gazı","NH3","NH₃","azane"],"tanim":["Atmosferdeki başlıca bazik gaz olan azot ve hidrojenden oluşan bir bileşiktir (NH₃).","Tarım ve hayvancılık etkinliklerinden salınır; gaz fazında bulunur.","Sülfürik asit ve nitrik asidi nötrleyerek amonyum sülfat ve amonyum nitrat gibi ikincil ince parçacıkları oluşturur."],"tanim_en":"The primary alkaline trace gas in the atmosphere that neutralizes acidic compounds to form ammonium salts.","bag":{"kavram":["aerosol-sinif","stokiyometri","asit-yagmuru"],"soru":["S14","S28"],"hesap":[]}},{"id":"ammonium","tr":"Amonyum","en":"Ammonium","kisa":"NH₄⁺","tur":"kavram","es":["amonyum iyonu","NH₄⁺","ammonium ion"],"tanim":["Amonyak gazının bir proton almasıyla oluşan tek yüklü katyondur (NH₄⁺).","Atmosferde serbest gaz olarak bulunmaz; sülfat ve nitrat anyonlarıyla tuz oluşturarak aerosol fazında yer alır.","Asidik kirleticilerin nötrlenmesini sağlar ve ince moddaki aerosol kütlesine önemli katkı yapar."],"tanim_en":"A positively charged polyatomic cation formed by protonation of ammonia, found predominantly in fine aerosol particles.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S28"],"hesap":[]}},{"id":"ammonium-nitrate","tr":"Amonyum nitrat","en":"Ammonium nitrate","kisa":"NH₄NO₃","tur":"kavram","es":["ikincil nitrat","NH₄NO₃","ammonium nitrate aerosol"],"tanim":["Amonyak gazı ile nitrik asit buharının nötrleşme tepkimesiyle oluşan ikincil inorganik aerosol bileşiğidir (NH₄NO₃).","Gazdan parçacığa dönüşüm yoluyla oluşur ve ince parçacık modunda (PM2.5) yer alır.","Sıcaklık arttığında tekrar gaz öncüllerine ayrışabilen yarı uçucu bir tuzdur."],"tanim_en":"A secondary inorganic aerosol compound formed by the reversible reaction between gas-phase ammonia and nitric acid.","bag":{"kavram":["aerosol-sinif"],"soru":["S14"],"hesap":[]}},{"id":"black-carbon","tr":"İs (siyah karbon)","en":"Black carbon","kisa":"BC","tur":"kavram","es":["siyah karbon","kurum","dizel isi","element karbon (EC)","BC"],"tanim":["Fosil yakıt ve biyokütlenin eksik yanması sonucu doğrudan atmosfere salınan, birincil ve güçlü soğurucu karbonlu aerosoldür.","Görünür ışık dalga boylarının tamamında güçlü soğurma yapar ve tek saçılma albedosu (ω) düşüktür.","Atmosfer tabakasını ısıtırken kar ve buz üzerine çökerek yüzey albedosunu düşürür ve erimeyi hızlandırır."],"tanim_en":"A primary carbonaceous aerosol produced by incomplete combustion that strongly absorbs solar radiation across all visible wavelengths.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan","pm"],"soru":["S1","S2","S3","S4","S5","S6"],"hesap":["etkin-sicaklik","zorlama","bulut-net","clausius"]}},{"id":"brown-carbon","tr":"Kahverengi karbon","en":"brown carbon","kisa":"","tur":"kavram","es":["BrC","kahverengi karbon aerosolü"],"tanim":["Biyokütle ve biyoyakıt yanmasından kaynaklanan, ışığı dalga boyuna bağlı olarak soğuran organik aerosol bileşenidir.","Özellikle morötesi ve mavi dalga boylarında soğurma yapar, uzun dalga boylarına doğru soğurması hızla azalır.","Işınımı soğurarak tek saçılma albedosunu düşürür ve bölgesel atmosferik ısınmaya katkı verir."],"tanim_en":"A light-absorbing organic aerosol component that absorbs solar radiation primarily at ultraviolet and shorter visible wavelengths.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan"],"soru":[],"hesap":[]}},{"id":"coarse-particles","tr":"İri parçacıklar","en":"Coarse particles","kisa":"PM10","tur":"kavram","es":["iri parçacık","kaba parçacıklar","coarse mode","kaba fraksiyon","PM10-2.5","iri mod"],"tanim":["Aerodinamik çapı 2,5 µm'den büyük olan atmosferik aerosol parçacıklarıdır.","Rüzgâr, deniz dalgaları ve mekanik sürtünme gibi fiziksel süreçlerle doğrudan üretilir; kütlece baskındır.","Yerçekimsel çökelme hızı yüksek olduğundan atmosferik ömrü kısadır ve üst solunum yollarında tutulur."],"tanim_en":"Atmospheric particles with aerodynamic diameters larger than 2.5 micrometers, predominantly produced by mechanical generation.","bag":{"kavram":["aerosol-sinif","pm","boyut-modlari"],"soru":["S14","S15","S16","S17","S19","S20"],"hesap":[]}},{"id":"desert-dust","tr":"Çöl tozu","en":"Desert dust","kisa":"","tur":"kavram","es":["mineral tozu","mineral dust","rüzgârla kalkan toz","toprak tozu","Mineral toz","mineral toz"],"tanim":["Kurak ve yarı kurak bölgelerden rüzgâr erozyonuyla atmosfere karışan birincil mineral aerosol türüdür.","Ağırlıklı olarak iri modda yer alır; silikatlar, kil mineralleri ve demir oksit içerir.","Güneş ışığını saçar, demir oksit içeriği nedeniyle kısa dalga boylarında bir miktar soğurma yapar ve uzun mesafelere taşınır."],"tanim_en":"A primary mineral aerosol entrained into the atmosphere by wind erosion over arid and semi-arid regions.","bag":{"kavram":["aerosol-sinif","pm"],"soru":["S14"],"hesap":[]}},{"id":"fine-particles","tr":"İnce parçacıklar","en":"Fine particles","kisa":"PM2.5","tur":"kavram","es":["ince parçacık","fine mode","ince mod","ince fraksiyon","fine particulate matter","ince aerosol"],"tanim":["Aerodinamik çapı 2,5 µm ve daha küçük olan aerosol parçacıklarıdır (PM2.5).","Yanma süreçleri ve gazdan parçacığa yoğuşma tepkimeleriyle oluşur.","Atmosferde günlerce kalarak uzun mesafelere taşınabilir ve solunum yoluyla akciğer alveollerine kadar ulaşır."],"tanim_en":"Atmospheric particles with aerodynamic diameters not exceeding 2.5 micrometers, primarily formed by combustion and condensation.","bag":{"kavram":["aerosol-sinif","pm","boyut-modlari"],"soru":["S14","S16","S17","S19","S21"],"hesap":[]}},{"id":"isoprene","tr":"İzopren","en":"Isoprene","kisa":"C₅H₈","tur":"kavram","es":["2-metilbütadien","biyojenik VOC","2-metil-1,3-bütadien","isoprene","C₅H₈","2-methyl-1,3-butadiene"],"tanim":["Bitki örtüsü tarafından atmosfere bol miktarda salınan, beş karbonlu uçucu organik bileşiktir (C₅H₈).","Gündüz saatlerinde güneş ışığı ve sıcaklıkla yapraklardan salınımı artar; atmosferik ömrü kısadır.","OH radikali ve ozonla hızla tepkimeye girerek düşük uçuculukta bileşikler üretir ve ikincil organik aerosol (SOA) oluşturur."],"tanim_en":"A biogenic volatile organic compound emitted by vegetation that oxidizes rapidly to produce secondary organic aerosol.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18"],"hesap":[]}},{"id":"nitrate-aerosol","tr":"Nitrat aerosolü","en":"Nitrate aerosol","kisa":"NO₃⁻","tur":"kavram","es":["partikül nitrat","nitrat parçacığı","NO3-","nitrate","nitrat","Nitrat iyonu"],"tanim":["Azot oksitlerin ve nitrik asidin atmosferde nötralleşmesi veya yoğuşmasıyla oluşan ikincil inorganik aerosol türü.","Atmosferde çoğunlukla ince modda (PM2,5) amonyum nitrat tuzu hâlinde bulunur.","Güneş ışığını saçar, asit çökelmesine katkıda bulunur ve hava kalitesini düşürür."],"tanim_en":"Nitrate aerosol is a secondary inorganic particle formed by the atmospheric oxidation and neutralization of nitrogen compounds.","bag":{"kavram":["aerosol-sinif","pm","koschmieder"],"soru":["S14","S21","S27"],"hesap":[]}},{"id":"nitric-acid","tr":"Nitrik asit","en":"Nitric acid","kisa":"HNO₃","tur":"kavram","es":["hidrojen nitrat","kezzap","HNO3","HNO₃"],"tanim":["Azot dioksit gazının hidroksil radikaliyle üç cisimli tepkimesi sonucu oluşan tek protonlu kuvvetli bir inorganik asit (HNO₃).","Suda tamamen H⁺ ve NO₃⁻ iyonlarına ayrışarak yağış suyunun asitliğini artırır.","Kutup stratosfer bulutlarının yapısına katılarak klor aktivasyonu ve denitrifikasyon olaylarına zemin hazırlar."],"tanim_en":"Nitric acid is a strong atmospheric acid formed by the oxidation of nitrogen dioxide that contributes to acid deposition and polar stratospheric cloud formation.","bag":{"kavram":["aerosol-sinif","asit-yagmuru","psc"],"soru":["S14","S21","S27","S32"],"hesap":["ph-asit"]}},{"id":"organic-carbon","tr":"Organik karbon","en":"Organic carbon","kisa":"OC","tur":"kavram","es":["organik aerosol","organik karbon parçacığı","OC","partikül organik karbon"],"tanim":["Atmosferik parçacıklar içinde C–H ve C–O kimyasal bağları içeren organik bileşiklerin karbon kütlesi payı.","Hem doğrudan biyolojik salımlar ve yanmadan hem de uçucu organik bileşiklerin yükseltgenmesiyle oluşan ikincil organik aerosolden kaynaklanır.","Işığı çoğunlukla saçar ve higroskopik özelliklerine bağlı olarak bulut yoğuşma çekirdeği görevi yapar."],"tanim_en":"Organic carbon represents the fraction of particulate matter containing carbon-hydrogen and carbon-oxygen chemical bonds.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18"],"hesap":[]}},{"id":"oxidant","tr":"Oksidan","en":"Oxidant","kisa":"","tur":"kavram","es":["yükseltgen","atmosferik oksidan"],"tanim":["Atmosferde diğer kimyasal türlerden elektron alan veya onlara oksijen aktararak yükseltgenmelerini sağlayan kimyasal olarak etkin tür.","Troposferdeki başlıca örnekleri hidroksil radikali (OH), ozon (O₃) ve nitrat radikalidir (NO₃).","Kükürt dioksit ve organik gazları yükseltgeyerek sülfat ve ikincil organik aerosol gibi parçacıkların oluşumunu başlatır."],"tanim_en":"An oxidant is a reactive chemical agent capable of oxidizing trace gas molecules and pollutants in the atmosphere.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18","S29","S31","S44"],"hesap":[]}},{"id":"pollen","tr":"Polen","en":"Pollen","kisa":"","tur":"kavram","es":["çiçek tozu","biyolojik parçacık","biyolojik aerosol","aerosol polen"],"tanim":["Bitkiler tarafından çoğalma amacıyla havaya salınan biyolojik kökenli birincil aerosol parçacığı.","Çapı çoğunlukla 2,5 µm'den büyük olduğu için aerosol boyut dağılımında mekanik kaynaklı iri modda yer alır.","Yerçekimsel çökelmeyle atmosferden kısa sürede uzaklaşır, ancak bulutlarda buz çekirdeklenmesini tetikleyebilir."],"tanim_en":"Pollen is a coarse primary biological particle emitted by vegetation that rapidly settles under gravity.","bag":{"kavram":["aerosol-sinif"],"soru":["S14"],"hesap":[]}},{"id":"primary-aerosol","tr":"Birincil aerosol","en":"Primary aerosol","kisa":"","tur":"kavram","es":["primer aerosol","doğrudan salınan parçacık"],"tanim":["Kaynaktan atmosfere doğrudan katı veya sıvı parçacık biçiminde salınan aerosol türü.","Deniz tuzu, çöl tozu ve polen gibi mekanik iri parçacıkların yanında yanmadan çıkan ince isi de kapsar.","Atmosferde kimyasal gaz dönüşümü gerektirmeden partikül yükünü ve doğrudan ışınım etkisini belirler."],"tanim_en":"A primary aerosol is a particulate matter component emitted directly into the atmosphere in solid or liquid form.","bag":{"kavram":["aerosol-sinif"],"soru":["S17"],"hesap":[]}},{"id":"sea-salt","tr":"Deniz tuzu","en":"Sea salt","kisa":"NaCl","tur":"kavram","es":["deniz spreyi","sea salt aerosol","deniz tuzu aerosolü","NaCl"],"tanim":["Okyanus yüzeyinde dalga kırılması ve köpük kabarcıklarının patlamasıyla havaya fırlatılan birincil doğal aerosol.","Bileşimi büyük oranda NaCl tuzundan oluşur ve mekanik üretim nedeniyle çoğunlukla iri modda bulunur.","Çok higroskopik olduğu için denizel sınır tabakada etkin bir bulut yoğuşma çekirdeği (CCN) olarak davranır ve güneş ışığını saçar."],"tanim_en":"Sea salt is a primary natural aerosol produced by breaking waves that acts as an efficient cloud condensation nucleus.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S16"],"hesap":[]}},{"id":"secondary-aerosol","tr":"İkincil aerosol","en":"Secondary aerosol","kisa":"","tur":"kavram","es":["sekonder aerosol","gazdan dönüşen parçacık","gazdan oluşan aerosol"],"tanim":["Atmosferde gaz fazındaki öncül maddelerin kimyasal tepkimelerle düşük uçuculukta ürünlere dönüşmesi ve yoğuşmasıyla oluşan parçacık.","Sülfat, nitrat, amonyum ve ikincil organik aerosol (SOA) türlerini kapsar.","Çoğunlukla 1 µm'den küçük ince modda yer alarak güneş ışığını saçar ve görüş mesafesini azaltır."],"tanim_en":"A secondary aerosol is particulate matter produced in the atmosphere by the chemical transformation and condensation of precursor gas molecules.","bag":{"kavram":["aerosol-sinif","asit-yagmuru"],"soru":["S14","S17","S28","S31"],"hesap":[]}},{"id":"secondary-organic-aerosol","tr":"İkincil organik aerosol","en":"Secondary organic aerosol","kisa":"SOA","tur":"kavram","es":["sekonder organik aerosol","SOA"],"tanim":["Uçucu organik bileşiklerin atmosferik oksidanlarla tepkimeye girerek düşük uçuculukta bileşikler oluşturması ve bunların yoğuşmasıyla meydana gelen organik parçacık.","İzopren ve terpen gibi biyojenik salımlar ile insan kaynaklı hidrokarbonların yükseltgenmesinden kaynaklanır.","Aerosol boyut dağılımında ince modda yer alır, güneş ışığını saçar ve iklim üzerinde doğrudan ile dolaylı ışınımsal etki yapar."],"tanim_en":"Secondary organic aerosol is particulate matter formed through the atmospheric oxidation and condensation of volatile organic compounds.","bag":{"kavram":["aerosol-sinif","leighton"],"soru":["S14","S18"],"hesap":[]}},{"id":"sulfate-aerosol","tr":"Sülfat aerosolü","en":"Sulfate aerosol","kisa":"SO₄²⁻","tur":"kavram","es":["sülfat","ikincil sülfat","sülfat parçacığı","sülfat partikülleri","sulfate particles","sülfat aerosol damlacığı"],"tanim":["Kükürt dioksitin (SO₂) atmosferde yükseltgenerek sülfürik asit ve sülfat tuzlarına dönüşmesiyle oluşan ikincil inorganik aerosol.","Tek saçılma albedosu bire yakın (ω ≈ 1) olduğu için güneş ışığını güçlü şekilde saçar ve yüzey sıcaklığını düşürür.","Troposferde yaklaşık bir haftalık ömre sahipken stratosfere ulaşan volkanik sülfat aerosolü yaklaşık bir yıllık e-katlanma süresiyle kalır."],"tanim_en":"Sulfate aerosol is a secondary inorganic particle formed by sulfur dioxide oxidation that efficiently scatters solar radiation and cools the climate.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan","volkan-aerosol"],"soru":["S14","S18","S25","S27","S28","S29"],"hesap":[]}},{"id":"sulfuric-acid","tr":"Sülfürik asit","en":"Sulfuric acid","kisa":"H₂SO₄","tur":"kavram","es":["zaç yağı","H₂SO₄","sulphuric acid","sülfat aerosolünün asidi"],"tanim":["Kükürt dioksidin atmosferde yükseltgenmesiyle (SO₂ → SO₃ → H₂SO₄) oluşan, seyreltik çözeltide iki proton veren kuvvetli bir asit.","Seyreltik yağmur suyunda her molü 2 mol H⁺ verir; kitabın pH hesabında [H⁺] = [HNO₃] + 2[H₂SO₄].","Düşük buhar basıncı nedeniyle gazdan parçacığa dönüşerek ikincil sülfat aerosollerini ve asit yağmurunu oluşturan temel bileşiktir."],"tanim_en":"A strong diprotic mineral acid formed by the atmospheric oxidation of sulfur dioxide that drives secondary sulfate particle formation and acid precipitation.","bag":{"kavram":["aerosol-sinif","asit-yagmuru","volkan-aerosol"],"soru":["S14","S27","S28","S29","S31","S33"],"hesap":["ph-asit"]}},{"id":"volatile-organic-compound","tr":"Uçucu organik bileşikler","en":"volatile organic compounds","kisa":"VOC","tur":"kod","es":["UOB","VOC"],"tanim":["Oda sıcaklığında yüksek buhar basıncına sahip olan ve atmosfere kolayca buharlaşan karbon temelli organik bileşikler.","Troposferde OH radikaliyle tepkimeye girerek peroksi radikalleri (RO₂) oluşturur; bu radikaller NO'yu O₃ harcamadan NO₂'ye yükseltger.","Hem fotokimyasal dumanın ve troposferik ozonun hem de ikincil organik aerosollerin (SOA) temel öncülüdür."],"tanim_en":"An organic chemical compound having high vapour pressure at ambient temperature that acts as a key precursor to tropospheric ozone and secondary organic aerosol.","bag":{"kavram":["aerosol-sinif","leighton","titrasyon"],"soru":["S43","S44"],"hesap":[]}},{"id":"combustion","tr":"Yanma","en":"Combustion","kisa":"","tur":"surec","es":["yakma","fosil yakıt yanması"],"tanim":["Bir yakıtın oksijenle hızlı tepkimeye girerek ısı, ışık ve yanma ürünleri açığa çıkardığı yüksek sıcaklıklı kimyasal süreç.","Fosil yakıt ve biyokütle yakılması atmosfere CO₂, CO, NOₓ, SO₂ ve birincil parçacıklar salar.","İnce aerosol modunda yer alan dizel isi gibi birincil parçacıkların ve asit yağmuru ile duman öncülü gazların ana antropojenik kaynağıdır."],"tanim_en":"A high-temperature exothermic chemical reaction between a fuel and an oxidant that produces thermal energy and emits air pollutants.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S28"],"hesap":[]}},{"id":"condensation","tr":"Yoğuşma","en":"Condensation","kisa":"","tur":"surec","es":["yoğunlaşma","buhar yoğuşması"],"tanim":["Gaz ya da buhar fazındaki bir maddenin sıvı faza geçmesi; buhar hâlinden sıvı hâle geçiş.","Süreç sırasında çevreye gizli ısı salınır; atmosferde su buharı bağıl nem %100'e ulaştığında veya aşırı doygunlukta yoğuşur.","Atmosferde bulut damlacıklarının oluşumunu, bulut tabanını (LCL) ve gazdan parçacığa dönüşümle ince aerosol modlarının büyümesini belirler."],"tanim_en":"The phase transition of a substance from the vapour state to the liquid state, accompanied by the liberation of latent heat.","bag":{"kavram":["aerosol-sinif","boyut-modlari","lcl"],"soru":["S8","S11","S12","S14","S15","S17"],"hesap":["lcl"]}},{"id":"gas-to-particle-conversion","tr":"Gazdan parçacığa dönüşüm","en":"Gas-to-particle conversion","kisa":"GPC","tur":"surec","es":["gazdan parçacık oluşumu","ikincil aerosol oluşumu","GPC"],"tanim":["Atmosferdeki gaz fazı öncüllerin kimyasal tepkimelerle düşük uçuculukta ürünlere dönüşerek yeni parçacık oluşturması veya mevcut parçacıklar üzerinde yoğuşması süreci.","Kükürt dioksit, azot oksitler, amonyak ve uçucu organik bileşiklerin hidroksil radikali gibi oksidanlarla yükseltgenmesi yoluyla gerçekleşir.","Atmosferdeki 2,5 µm altındaki ikincil ince parçacıkların (sülfat, nitrat, amonyum ve SOA) tamamını meydana getirir."],"tanim_en":"The transformation of trace gas precursor molecules into low-volatility compounds that form secondary aerosol particles by nucleation or condensation.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S17","S33"],"hesap":[]}},{"id":"mechanical-generation","tr":"Mekanik üretim","en":"Mechanical generation","kisa":"","tur":"surec","es":["mekanik parçalanma","mekanik aşınma"],"tanim":["Rüzgâr, dalga kırılması veya sürtünme gibi mekanik kuvvetlerin yeryüzünden doğrudan katı veya sıvı parçacık koparması süreci.","Parçacık küçüldükçe yüzey/hacim oranı ve gereken yüzey enerjisi aşırı arttığı için mekanik üretim 1 µm altındaki parçacıkları üretemez.","Deniz tuzu, çöl tozu ve polen gibi 2,5 µm'den büyük iri modlu birincil aerosollerin temel oluşum yoludur."],"tanim_en":"The production of coarse primary aerosol particles directly from the surface through physical forces such as wind shear and wave breaking.","bag":{"kavram":["aerosol-sinif","stokes"],"soru":["S14","S17"],"hesap":[]}},{"id":"first-order-reaction","tr":"Birinci mertebe tepkime","en":"first-order reaction","kisa":"","tur":"kavram","es":["birinci derece kayıp","first-order decay","birinci mertebe kinetik","birinci mertebe kayıp","first-order loss","üstel azalma"],"tanim":["Tepkime hızının yalnızca tek bir türün derişimiyle doğru orantılı olduğu kimyasal dönüşüm süreci.","Hız denklemi hız = k[A] biçiminde olup birinci mertebe hız sabitinin birimi s⁻¹ veya 1/yıl; türün atmosferik ömrü ise τ = 1/k formülüyle hesaplanır.","Atmosferdeki fotoliz tepkimeleri ile bir bileşenin derişimi neredeyse sabit kalan bir reaktifle tepkimeye girdiği sözde birinci mertebe kayıpların matematiksel temelidir."],"tanim_en":"A chemical reaction whose rate is directly proportional to the concentration of a single reacting chemical species.","bag":{"kavram":["arrhenius","ustel","omur"],"soru":["S31","S37","S40"],"hesap":[]}},{"id":"three-body-reaction","tr":"Üç cisimli tepkime","en":"three-body reaction","kisa":"O + O₂ + M","tur":"kavram","es":["üçüncü cisim tepkimesi","Üç cisimli birleşme tepkimesi","termolecular reaction","termoleküler tepkime"],"tanim":["İki kimyasal türün birleşerek tek bir ürün oluştururken açığa çıkan aşırı enerjiyi ortamdaki üçüncü bir cismin uzaklaştırdığı kimyasal tepkime.","Hız sabiti birimi cm⁶ molekül⁻² s⁻¹ olup tepkime hızı ortamın sayı yoğunluğu ve basınç ile doğru orantılı olarak artar.","Stratosferde ozon oluşumunun temel adımıdır ve sıcaklık azaldıkça tepkime hızı genellikle yükselir."],"tanim_en":"A termolecular chemical reaction in which two colliding species combine into a single product while a third body removes the surplus energy.","bag":{"kavram":["arrhenius","asit-yagmuru","chapman"],"soru":["S41","S43"],"hesap":["chapman-o"]}},{"id":"activation-energy","tr":"Aktivasyon enerjisi","en":"activation energy","kisa":"Eₐ","tur":"olcu","es":["aktifleşme enerjisi","Ea sembolü","etkinleşme enerjisi","enerji engeli","Eₐ"],"tanim":["Bir kimyasal tepkimenin başlayabilmesi ve tepkenlerin geçiş durumuna ulaşabilmesi için aşılması gereken minimum enerji engeli.","Arrhenius denkleminde Eₐ simgesiyle yer alır; birimi J/mol veya kJ/mol olup atmosfer kimyasında çoğunlukla Eₐ/R oranı olarak Kelvin cinsinden ifade edilir.","Tepkime hız sabitinin sıcaklığa olan duyarlılığını belirler; yüksek aktivasyon enerjisine sahip tepkimeler sıcaklık artışıyla çok daha hızlı ivmelenir."],"tanim_en":"The minimum amount of energy required by reactant molecules to overcome the potential barrier and initiate a chemical reaction.","bag":{"kavram":["arrhenius"],"soru":["S37","S40"],"hesap":["ea-iki-nokta"]}},{"id":"pre-exponential-factor","tr":"Ön çarpan","en":"pre-exponential factor","kisa":"A","tur":"olcu","es":["ön üstel çarpan","frekans faktörü","A sembolü","Arrhenius A","üstel öncesi çarpan","A faktörü"],"tanim":["Arrhenius denkleminde üstel fonksiyonun önünde yer alan ve sıcaklık sonsuza yaklaştığındaki kuramsal hız sabitini gösteren parametre.","A simgesiyle gösterilir; birimi tepkimenin mertebesine göre hız sabitiyle aynıdır (ikinci mertebe için cm³ molekül⁻¹ s⁻¹).","Reaktif moleküller arasındaki çarpışma sıklığı ile tepkimeye yol açan uygun geometrik yönelim olasılığının çarpımını ifade eder."],"tanim_en":"The pre-exponential constant A in the Arrhenius equation that represents the frequency of molecular collisions with the correct steric orientation.","bag":{"kavram":["arrhenius"],"soru":["S37","S40"],"hesap":["arrhenius"]}},{"id":"acid-deposition","tr":"Asit çökelmesi","en":"acid deposition","kisa":"","tur":"kavram","es":["asit birikimi","asitli çökelme","acidic deposition"],"tanim":["Kükürt ve azot içeren kirleticilerin atmosferik taşınımı sonucu asidik maddelerin yeryüzüne ıslak veya kuru yollarla aktarılması.","Islak çökelme ile gaz ve aerosol parçacıklarının doğrudan tutunması olan kuru çökelme mekanizmalarının toplamını kapsar.","Toprak, göl ve nehir sularında pH değerini düşürerek ekosistemlerde, ormanlarda ve yapı malzemelerinde bozulmaya yol açar."],"tanim_en":"The transfer of acidic substances from the atmosphere to the Earth surface through both wet and dry deposition pathways.","bag":{"kavram":["asit-yagmuru"],"soru":["S21"],"hesap":[]}},{"id":"limestone","tr":"Kireçtaşı","en":"limestone","kisa":"CaCO₃","tur":"kavram","es":["kalker","kalsiyum karbonat","CaCO₃","calcium carbonate"],"tanim":["Ağırlıklı olarak kalsiyum karbonat (CaCO₃) mineralinden oluşan, atmosferik asitleri nötrleme kapasitesine sahip tortul bir kayaç türü.","Asit yağmurundaki hidrojen iyonlarıyla tepkimeye girerek serbest asitliği tüketir ve ortamı tamponlar.","Kireçtaşı içeren havzalardaki göller asit yağışlarına karşı direnç göstererek pH dengesini granit havzalara göre çok daha iyi korur."],"tanim_en":"A sedimentary rock composed mainly of calcium carbonate that acts as a natural buffer against acidic deposition.","bag":{"kavram":["asit-yagmuru","stokiyometri"],"soru":["S29"],"hesap":[]}},{"id":"marble","tr":"Mermer","en":"marble","kisa":"","tur":"kavram","es":["mermer aşınması","metamorfik kireçtaşı"],"tanim":["Kireçtaşının yüksek sıcaklık ve basınç altında yeniden kristallenmesiyle oluşan kalsiyum karbonat (CaCO₃) esaslı metamorfik kayaç.","Sülfürik asit içeren asit yağmuruyla tepkimeye girerek yüzeyinde çözünür alçı oluşturur.","Tarihi yapılarda ve heykellerde asit çökelmesi nedeniyle yüzey kabartmalarının silinmesine ve yapısal malzeme kaybına uğrar."],"tanim_en":"A metamorphic rock consisting predominantly of calcium carbonate that undergoes chemical degradation when exposed to acidic precipitation.","bag":{"kavram":["asit-yagmuru","stokiyometri"],"soru":["S29"],"hesap":[]}},{"id":"strong-acid","tr":"Kuvvetli asit","en":"strong acid","kisa":"","tur":"kavram","es":["güçlü asit","tam ayrışan asit"],"tanim":["Sulu çözeltisinde moleküler yapısı neredeyse tamamen iyonlarına ayrışarak ortama hidronyum veren asit türü.","Atmosfer kimyasında kükürt dioksit ve azot oksitlerin yükseltgenmesiyle oluşan H₂SO₄ ve HNO₃ temel kuvvetli asitlerdir.","Yağmur suyunun pH değerini temiz yağmur referansı olan 5,6 seviyesinin altına indirerek asit yağmurunu oluşturur."],"tanim_en":"An acid that dissociates completely into ions in an aqueous solution, such as sulfuric acid and nitric acid in rain droplets.","bag":{"kavram":["asit-yagmuru"],"soru":["S27"],"hesap":[]}},{"id":"third-body","tr":"Üçüncü cisim","en":"third body","kisa":"[M]","tur":"kavram","es":["çarpışan üçüncü cisim","çarpışma partneri","third body collider","[M]","üçüncü cisim molekülü","üçüncü gövde"],"tanim":["Üç cisimli tepkimede ürünün fazla enerjisini çarpışarak alıp götüren, kendisi değişmeden çıkan molekül; M ile gösterilir (çoğunlukla N₂ ya da O₂).","[M] havanın toplam sayı yoğunluğudur (molekül/cm³; kitapta 30 km'de 3,8 × 10¹⁷). Üç cisimli tepkimenin hız sabiti cm⁶ molekül⁻² s⁻¹ biriminde.","Yükseklikle [M] azaldığından R2 (O + O₂ + M → O₃ + M) yüksekte yavaşlar; M olmadan birleşen atom fazla enerjiyle hemen yeniden ayrışır."],"tanim_en":"A third body is a molecule, such as N₂ or O₂, that takes up the excess energy released when two species combine, so that the product is stabilised without the third body itself being changed.","bag":{"kavram":["asit-yagmuru","psc","arrhenius"],"soru":["S41"],"hesap":["chapman-o"]}},{"id":"transboundary-pollution","tr":"Sınır aşan kirlilik","en":"transboundary pollution","kisa":"","tur":"kavram","es":["sınır aşan hava kirliliği","transboundary air pollution","sınır ötesi kirlilik","uzun menzilli kirlilik"],"tanim":["Bir ülkenin sınırları içinde salınan kirleticilerin atmosferik hava hareketleriyle yüzlerce kilometre taşınarak başka ülkelerin topraklarına veya sularına çökmesi olayı.","Özellikle SO₂ ve NOₓ gibi öncül gazların atmosferik taşınım süresince sülfat ve nitrata dönüşmesiyle asit çökelmesi biçiminde ortaya çıkar.","Çevre kirliliğinin ulusal sınırları aşması nedeniyle uluslararası sözleşmeler ve sınır ötesi hava kirliliği protokolleri gerektirir."],"tanim_en":"Air pollution that originates in one country and creates environmental damage in another country after long-range atmospheric transport.","bag":{"kavram":["asit-yagmuru"],"soru":[],"hesap":[]}},{"id":"weathering","tr":"Ayrışma","en":"weathering","kisa":"","tur":"kavram","es":["kimyasal ayrışma","kayaç bozunması","bozunma","chemical weathering"],"tanim":["Yerkabuğundaki kayaç ve minerallerin atmosfer koşullarına maruz kalarak bulundukları yerde fiziksel veya kimyasal yollarla parçalanıp bozunması süreci.","Kimyasal ayrışmada atmosferik CO₂ gazının yağmur suyunda oluşturduğu karbonik asit ile asit yağmuru bileşenleri silikat ve karbonat minerallerini çözer.","Jeolojik zaman ölçeğinde atmosferdeki karbondioksitin dengelenmesinde ve toprak oluşumunda birincil rol oynar."],"tanim_en":"The chemical or mechanical breakdown of rock materials at the Earth surface under the action of atmospheric agents.","bag":{"kavram":["asit-yagmuru"],"soru":["S26","S27","S29"],"hesap":["ph-temiz"]}},{"id":"teragram","tr":"Teragram","en":"teragram","kisa":"Tg","tur":"birim","es":["Tg","10¹² g","bir milyon ton"],"tanim":["Metrik sistemde 10¹² grama yani 10⁹ kilograma veya bir milyon tona denk gelen kütle birimi.","Sembolü Tg olup atmosfer kimyası ve iklim çalışmalarında küresel atmosferik gaz yüklerini ve yıllık salım miktarlarını göstermek için kullanılır.","Kutu modellerinde gazların atmosferik ömrü hesaplanırken toplam atmosferik yük ile yıllık kayıp hızı bu birim üzerinden oranlanır."],"tanim_en":"A metric unit of mass equal to 10¹² grams or one megatonne, commonly applied to quantify global atmospheric pollutant burdens and annual emission flux.","bag":{"kavram":["atmosfer-kutlesi","omur","kutu-modeli"],"soru":["S4","S36"],"hesap":[]}},{"id":"column-density","tr":"Sütun yoğunluğu","en":"column density","kisa":"","tur":"kavram","es":["hava sütunu","air column","Hava sütunu","atmospheric column","kolon yoğunluğu","dikey sütun miktarı"],"tanim":["Yeryüzündeki birim yatay alanın üzerinde atmosferin üst sınırına kadar uzanan dikey hava sütunundaki toplam parçacık veya molekül sayısı.","Birimi molekül/cm² veya mol/m² olup toplam ozon miktarını belirtmek için Dobson birimi yaygın olarak kullanılır.","Uydu uzaktan algılama aygıtları ile doğrudan ölçülerek gazların optik derinliği ve ışınım soğurması hesaplanır."],"tanim_en":"The total number of gas molecules or particles per unit area integrated along a vertical path through the atmosphere.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4"],"hesap":[]}},{"id":"dry-air","tr":"Kuru hava","en":"dry air","kisa":"","tur":"kavram","es":["kuru hava bileşimi","su buharı içermeyen hava"],"tanim":["İçerisindeki değişken su buharı tamamen uzaklaştırılmış, sabit bileşenli kuramsal atmosferik gaz karışımı.","Mol kesri olarak yaklaşık %78 N₂, %21 O₂ ve %0,93 Ar içerir; ortalama mol kütlesi 28,97 g/mol kabul edilir.","Meteoroloji ve atmosfer kimyasında nem hesaplamaları, karışma oranı ve gaz sabitleri için standart referans ortamdır."],"tanim_en":"Atmospheric air from which all water vapor has been removed, consisting primarily of nitrogen, oxygen, and argon with an average molar mass near 29 g/mol.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4","S11"],"hesap":[]}},{"id":"methane","tr":"Metan","en":"methane","kisa":"CH₄","tur":"kavram","es":["CH4","bataklık gazı","metan gazı","marsh gas","CH₄"],"tanim":["En basit hidrokarbon yapısındaki kimyasal tür ve karbondioksitten sonraki en etkili ikinci insan kaynaklı sera gazı.","Küresel ortalama atmosferik karışım oranı yaklaşık 1934 ppb ve atmosferdeki toplam yükü yaklaşık 5600 Tg düzeyinde bulunur.","Troposferde yaklaşık 10 yıllık atmosferik ömrüyle iyi karışmış bir gazdır; temel yutağı hidroksil (OH) radikaliyle tepkimesidir."],"tanim_en":"An organic trace gas molecule that acts as the second most important anthropogenic greenhouse contributor with an atmospheric lifetime of approximately 10 years.","bag":{"kavram":["atmosfer-kutlesi","karisim-orani","sera-etkisi"],"soru":["S4","S5","S15","S36","S37","S38"],"hesap":[]}},{"id":"nitrogen-oxides","tr":"Azot oksitler","en":"nitrogen oxides","kisa":"NOₓ","tur":"kavram","es":["NOx","azot oksitleri","Azot oksitleri","NOₓ"],"tanim":["Atmosfer kimyasında azot monoksit (NO) ve azot dioksit (NO₂) bileşiklerinin toplamını belirten kimyasal terim.","Fosil yakıt yanması ve motorlu taşıt trafiğiyle salınan, ömrü troposferde saatler ile günler arasında değişen reaktif gaz grubudur.","Troposferik ozon ve fotokimyasal duman oluşumunda anahtar öncül olarak rol alır; havadaki oksidasyonuyla nitrik aside dönüşerek asit yağmuruna yol açar."],"tanim_en":"The atmospheric group comprising nitric oxide and nitrogen dioxide that serves as a key precursor to tropospheric ozone and photochemical smog.","bag":{"kavram":["atmosfer-kutlesi","aerosol-sinif","asit-yagmuru"],"soru":[],"hesap":[]}},{"id":"short-lived-gas","tr":"Kısa ömürlü gaz","en":"short-lived gas","kisa":"","tur":"kavram","es":["short-lived species","kısa ömürlü tür","kısa ömürlü iklim zorlayıcı"],"tanim":["Atmosferik ömrü küresel troposferik karışma süresinden (yaklaşık 1 yıl) belirgin şekilde daha kısa olan kimyasal tür.","Atmosferde homojen dağılacak zaman bulamadığından derişimi emisyon kaynaklarının yakınında yüksek kalır ve mekânsal değişkenlik gösterir.","NO₂, OH ve CO gibi türleri kapsar; bu gazların salımlarının azaltılması hava kalitesine ve iklime hızla yansır."],"tanim_en":"An atmospheric trace chemical whose lifetime is substantially shorter than the global mixing timescale, leading to pronounced spatial variability near emission regions.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S36","S38"],"hesap":[]}},{"id":"well-mixed-gas","tr":"İyi karışmış gaz","en":"well-mixed gas","kisa":"","tur":"kavram","es":["homojen karışmış gaz","homojen gaz","homojen dağılmış gaz","well-mixed greenhouse gas"],"tanim":["Atmosferdeki kalış ömrü küresel hava karışma süresinden (yaklaşık 1 yıl) çok daha uzun olan kimyasal gaz.","Troposfer genelinde homojen bir dağılım sergiler; yeryüzünde ölçülen karışım oranı değeri bütün dikey sütunu güvenle temsil eder.","Karbondioksit (CO₂), metan (CH₄) ve diazot monoksit (N₂O) gibi uzun ömürlü sera gazlarını kapsar."],"tanim_en":"An atmospheric trace gas component whose lifetime exceeds the global mixing timescale, resulting in a spatially uniform mixing ratio throughout the troposphere.","bag":{"kavram":["atmosfer-kutlesi","omur"],"soru":["S38"],"hesap":[]}},{"id":"air-density","tr":"Hava yoğunluğu","en":"air density","kisa":"ρ","tur":"olcu","es":["kütle yoğunluğu","yoğunluk","havanın yoğunluğu"],"tanim":["Birim hacimdeki havanın kütlesi.","Birimi kg/m³ olup deniz seviyesinde standart koşullarda yaklaşık 1,2 kg/m³ olarak ölçülür; irtifa arttıkça üstel olarak azalır.","Hidrostatik denge, dikey basınç gradyanı ve atmosfer kütlesi hesaplamalarında temel fiziksel durum büyüklüğüdür."],"tanim_en":"The mass of air per unit volume, typically measured in kilograms per cubic meter.","bag":{"kavram":["atmosfer-kutlesi","sayi-yogunlugu","stokes"],"soru":["S1","S15","S16","S17","S40","S41"],"hesap":["aerosol-mod","stokes"]}},{"id":"hydrostatic-balance","tr":"Hidrostatik denge","en":"hydrostatic balance","kisa":"","tur":"yontem","es":["hydrostatic equilibrium"],"tanim":["Atmosferde yukarı doğru yönelen düşey basınç gradyan kuvveti ile aşağı doğru çeken yerçekimi kuvvetinin tam dengede olması durumu.","Düşey eksende dP/dz = −ρg diferansiyel denklemiyle ifade edilir.","Büyük ölçekli atmosfer dinamiğinin temel kabullerindendir; yüzey basıncından toplam atmosfer kütlesinin hesaplanmasına olanak tanır."],"tanim_en":"The condition where the upward vertical pressure gradient force exactly balances the downward gravitational force in the atmosphere.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4"],"hesap":["atmosfer-kutlesi"]}},{"id":"diffuse-radiation","tr":"Yaygın (difüz) ışınım","en":"Diffuse radiation","kisa":"","tur":"kavram","es":["dağınık ışınım","saçılan ışık","difüz ışık","saçılan gök ışığı","yayılı ışınım"],"tanim":["Güneşten gelen ışınımın atmosferdeki gaz molekülleri ve aerosol parçacıkları tarafından saçılmasıyla gökyüzünün her yönünden yeryüzüne ulaşan güneş ışınımı.","Birimi W/m² olup doğrudan gelen güneş demetiyle birlikte toplam küresel ışınımı oluşturur.","Bulutlu ve yoğun puslu günlerde doğrudan ışın engellenirken yüzeye ulaşan güneş ışınımının neredeyse tamamı yaygın ışıktan meydana gelir."],"tanim_en":"Solar radiation reaching the Earth surface after its direction has been altered by scattering from atmospheric molecules and aerosol particles.","bag":{"kavram":["beer-lambert","aerosol-dogrudan"],"soru":["S24","S25"],"hesap":[]}},{"id":"direct-beam","tr":"Doğrudan ışın","en":"direct beam","kisa":"","tur":"kavram","es":["direkt ışınım","doğrudan güneş ışınımı","direct solar radiation"],"tanim":["Güneş diskinden çıkıp atmosfer boyunca yön değiştirmeden ve saçılmaya uğramadan doğrudan yeryüzüne varan paralel güneş ışınımı demeti.","Şiddeti W/m² birimiyle ifade edilir ve soğurucu ile saçıcı tabakadan geçerken Beer–Lambert yasasına göre üstel olarak zayıflar.","Yeryüzünde net gölge oluşumunu sağlayan temel bileşendir; yaygın ışık ile toplanarak yeryüzünün toplam güneşlenme girdisini belirler."],"tanim_en":"Solar radiation traveling in a straight line from the solar disk to the surface without being scattered or absorbed by the atmosphere.","bag":{"kavram":["beer-lambert"],"soru":["S24","S25","S33"],"hesap":["egik-isin"]}},{"id":"optical-air-mass","tr":"Optik hava kütlesi","en":"optical air mass","kisa":"m","tur":"olcu","es":["optik hava kütlesi faktörü","eğik ışın yolu","eğik optik yol","Eğik ışın yolu","Eğik yol","Slant path"],"tanim":["Güneş ışınının atmosferden geçerken katettiği eğik optik yol uzunluğunun dikey (zenit) yol uzunluğuna oranını veren boyutsuz çarpan.","Düzlem paralel atmosferde yaklaşık 1/cos θ olarak hesaplanır; güneş tepedeyken 1 iken, θ = 60°'de 2 ve θ = 80°'de 5,76 değerini alır.","Beer–Lambert eşitliğinde dikey optik derinliği çarparak eğik gelen doğrudan ışının atmosferde katettiği fazladan yolu hesaba katar."],"tanim_en":"The ratio of the optical path length of a solar beam through the atmosphere at a given zenith angle to the path length vertically overhead.","bag":{"kavram":["beer-lambert"],"soru":["S24"],"hesap":["egik-isin"]}},{"id":"transmittance","tr":"Geçirgenlik","en":"transmittance","kisa":"I/I₀","tur":"olcu","es":["doğrudan geçen pay","geçen pay","transmisyon","Doğrudan ışın geçirimi","Direct beam transmittance","transmissivity"],"tanim":["Bir ortamdan geçen ışınımın, ortama gelen ışınıma oranıdır.","Boyutsuzdur ve 0 ile 1 arasında değer alır; kitapta I/I₀ olarak yazılır. Optik derinlikle bağı T = e^(−τ) biçiminde, eğik yolda T = exp(−τ / cos θ) olur.","Atmosferin güneş ışığını ne kadar geçirdiğini ölçer; 'transmission' süreci, 'transmittance' ise ölçülen oranı anlatır."],"tanim_en":"Transmittance is the ratio of the radiation transmitted by a medium to the radiation incident on it.","bag":{"kavram":["beer-lambert","tek-katman"],"soru":["S24","S25"],"hesap":["egik-isin","optik-derinlik","beer-kesit"]}},{"id":"rayleigh-scattering","tr":"Rayleigh saçılması","en":"Rayleigh scattering","kisa":"","tur":"surec","es":["moleküler saçılma","mavi ışık saçılması"],"tanim":["Işığın dalga boyundan çok küçük saçıcılar (hava molekülleri) tarafından saçılmasıdır.","Şiddet λ⁻⁴ ile orantılıdır: kısa dalga boyları (mavi) uzun dalga boylarından (kırmızı) çok daha güçlü saçılır.","Mavi gökyüzünü ve kırmızı gün batımını açıklar; aerosol boyutunda (D ≈ λ) saçılma Mie türüne geçer."],"tanim_en":"Rayleigh scattering is the scattering of radiation by particles much smaller than the wavelength, such as air molecules, with intensity proportional to λ⁻⁴.","bag":{"kavram":["beer-lambert","koschmieder"],"soru":["S24"],"hesap":[]}},{"id":"scattering","tr":"Saçılma","en":"scattering","kisa":"","tur":"surec","es":["ışık saçılması","ışık saçma","Işık saçılması","Light scattering","light scattering"],"tanim":["Işınımın atmosferdeki gaz molekülleri veya aerosol parçacıklarıyla etkileşime girerek foton enerjisi kaybolmaksızın yön değiştirmesi süreci.","Saçılma kesiti σₛ (cm²) veya saçılma katsayısı ile ölçülür; soğurma kesitiyle toplamı optik yok olma (sönüm) katsayısını verir.","Gökyüzünün mavi görünmesini sağlar, puslu havalarda görüş mesafesini sınırlar ve güneş ışığını uzaya geri saçarak gezegen albedosunu yükseltir."],"tanim_en":"The physical mechanism in which electromagnetic radiation is deflected in diverse directions by atmospheric particles or gas molecules without thermal conversion.","bag":{"kavram":["beer-lambert","aerosol-dogrudan","volkan-aerosol"],"soru":["S15","S18","S22","S23","S24","S25"],"hesap":["optik-derinlik","beer-kesit"]}},{"id":"unit-nanometer","tr":"Nanometre","en":"Nanometer","kisa":"nm","tur":"birim","es":["milimikron","dalga boyu birimi","nm"],"tanim":["Uzunluk birimidir: 1 nm = 10⁻⁹ m = 10⁻³ µm.","Kitapta aerosol boyutunu (nm'den yaklaşık 100 µm'ye) ve morötesi dalga boylarını ifade etmek için kullanılır.","Küçük parçacıkları ve fotolizin eşik dalga boyunu (örneğin O₂ için λ < 240 nm) karşılaştırmak için uygundur."],"tanim_en":"The nanometre is a unit of length equal to one billionth of a metre (10⁻⁹ m), used for particle sizes and wavelengths of light.","bag":{"kavram":["boyut-modlari","aerosol-sinif","fotoliz"],"soru":[],"hesap":[]}},{"id":"accumulation-mode","tr":"Birikme modu","en":"Accumulation mode","kisa":"","tur":"kavram","es":["birikim modu","akümülasyon modu"],"tanim":["Çapı yaklaşık 0,1–2,5 µm olan aerosol parçacıklarının boyut modudur (kitaptaki örnekte yarıçap ≈ 0,1 µm).","Parçacıklar pıhtılaşma ve yoğuşmayla büyüyerek bu modda 'birikir'; hem büyümesi hem çökelmesi yavaştır, bu yüzden en uzun ömürlü moddur.","Çapları görünür ışığın dalga boyuna (0,4–0,7 µm) yakın olduğundan kesit başına en verimli saçıcıdır; görüşü, saçılmayı ve bulut çekirdeği sayısını bu mod belirler."],"tanim_en":"The accumulation mode is the aerosol size range of roughly 0.1–2.5 µm in diameter, in which particles grow by coagulation and condensation, persist longest and dominate light scattering and visibility.","bag":{"kavram":["boyut-modlari","koschmieder"],"soru":["S15","S16","S20","S23"],"hesap":[]}},{"id":"aerosol-size-distribution","tr":"Aerosol boyut dağılımı","en":"Aerosol size distribution","kisa":"","tur":"kavram","es":["boyut spektrumu","parçacık boyut dağılımı","boyut dağılımı","size distribution"],"tanim":["Havadaki aerosol parçacıklarının farklı boyut sınıflarındaki göreli bolluğudur.","Aynı dağılım sayıyla (r⁰), kesitle (S = nπr², r²) ya da hacimle (V = n·4/3·πr³, r³) tartılabilir; tepe her tartımda başka modda çıkar.","Hangi niceliğin çizildiği eksen başlığından okunur; sayı çekirdek modunu, kesit birikme modunu, hacim iri modu gösterir."],"tanim_en":"The aerosol size distribution is the relative abundance of atmospheric aerosol particles in various size categories, weighted by number, surface area or volume.","bag":{"kavram":["boyut-modlari"],"soru":["S15"],"hesap":[]}},{"id":"coarse-mode","tr":"İri mod","en":"Coarse mode","kisa":"","tur":"kavram","es":["kaba mod","iri parçacık modu"],"tanim":["Çapı 2,5 µm'den büyük (D > 2,5 µm) aerosol parçacıklarının oluşturduğu boyut modudur.","Rüzgâr, dalga ve aşınma gibi mekanik süreçlerle oluşur ve kısa sürede çöker.","Sayıca azdır ama hacmi (kütlesi) en büyük moddur; PM10 kütlesini belirler."],"tanim_en":"The coarse mode is the aerosol size range of particles larger than about 2.5 µm in diameter, produced mainly by mechanical generation (wind, waves, abrasion) and dominating particle mass.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S10","S14","S15","S16","S23"],"hesap":[]}},{"id":"nucleation-mode","tr":"Çekirdek modu","en":"Nucleation mode","kisa":"","tur":"kavram","es":["çekirdeklenme modu","Aitken modu","nuclei mode","nükleasyon modu","Aitken çekirdekleri","Aitken mode"],"tanim":["Gazdan yeni doğan en küçük aerosol parçacıklarının modudur (r ≈ 0,005–0,01 µm).","Sayıca en çok, kütlece en az moddur; kesit ve hacim payı küçüktür.","Bazı kaynaklar 10–100 nm aralığını ayrı bir mod olarak adlandırır; kitapta çekirdek modu olarak geçer."],"tanim_en":"The nucleation mode is the smallest aerosol size range (radius about 0.005–0.01 µm), containing freshly formed particles that are most numerous but contribute least to mass.","bag":{"kavram":["boyut-modlari"],"soru":["S15","S16"],"hesap":[]}},{"id":"ultrafine-particles","tr":"Nano parçacık","en":"Ultrafine particles","kisa":"UFP","tur":"kavram","es":["nanopartikül","ultra ince parçacıklar","Ultra ince parçacıklar","ultra ince (nano) parçacıklar","UFP"],"tanim":["Çapı 0,1 µm'den küçük (D < 0,1 µm) aerosol parçacıklarıdır.","Kütlesi çok küçük olduğundan PM ölçümünde neredeyse görünmez; ama sayıca çoktur.","Difüzyonla solunum yolu duvarına ulaşır ve akciğerin en derin bölgesine (alveol) iner; mikron altı ve nano parçacıklar kana geçebilir."],"tanim_en":"Ultrafine particles are aerosol particles smaller than about 0.1 µm in diameter, which contribute little mass but are numerous and deposit deep in the lung.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S20"],"hesap":[]}},{"id":"cross-sectional-area","tr":"Kesit alanı","en":"cross-sectional area","kisa":"πR²","tur":"olcu","es":["kesit alanı derişimi","izdüşüm alanı"],"tanim":["Bir parçacığın ya da gök cisminin gelen paralel ışın demetine dik izdüşüm alanı.","Parçacık topluluklarında birim hacimdeki toplam kesit alanı S = nπr² bağıntısıyla belirlenir ve µm²/cm³ birimiyle ifade edilir.","Gelen ışınımın soğurulma ve saçılma miktarını doğrudan belirler; gezegenin güneş enerjisini yakalayan disk alanını temsil eder."],"tanim_en":"The geometric projected area of an atmospheric particle or planetary body perpendicular to incident radiation.","bag":{"kavram":["boyut-modlari","twomey","isinim-dengesi"],"soru":["S6","S15","S22"],"hesap":["etkin-sicaklik"]}},{"id":"sym-particle-diameter","tr":"Parçacık çapı","en":"particle diameter","kisa":"D","tur":"olcu","es":["D_p","çap","parçacık boyu"],"tanim":["Bir aerosol parçacığının ya da bulut damlasının doğrusal boyutu veya eşdeğer küresel genişliği.","Genellikle mikrometre (µm) ya da nanometre (nm) birimiyle verilir; r yarıçapının iki katı olarak (D = 2r) tanımlanır.","Parçacığın havada asılı kalma süresini, solunum yolundaki çökelme bölgesini ve optik saçılma verimini kontrol eder."],"tanim_en":"The linear physical dimension characterizing the geometric size of an airborne aerosol particle or cloud droplet.","bag":{"kavram":["boyut-modlari","pm","stokes"],"soru":["S4","S15","S16","S17","S20","S22"],"hesap":["stokes"]}},{"id":"sym-volume-concentration","tr":"Hacim derişimi","en":"volume concentration","kisa":"V","tur":"olcu","es":["parçacık hacmi","hacimsel derişim","hacim","toplam aerosol hacmi"],"tanim":["Birim hava hacminde bulunan aerosol parçacıklarının toplam geometrik hacmi.","Genellikle µm³/cm³ birimiyle ifade edilir; küresel parçacık yaklaşımında V = n(4/3)πr³ bağıntısıyla hesaplanır.","Parçacık yoğunluğu ile çarpıldığında doğrudan atmosferik kütle derişimine (µg/m³) dönüşür; kütle payının belirlenmesini sağlar."],"tanim_en":"The total geometric volume of suspended aerosol material contained within a unit volume of air.","bag":{"kavram":["boyut-modlari","aerosol-sinif"],"soru":["S1","S2","S3","S4","S15","S16"],"hesap":["aerosol-mod"]}},{"id":"brownian-diffusion","tr":"Brown difüzyonu","en":"Brownian diffusion","kisa":"","tur":"surec","es":["Brown hareketi","difüzyonla çökelme","Brownian motion"],"tanim":["Akışkan moleküllerinin rastgele ısıl çarpışmaları sonucu çok küçük aerosol parçacıklarının net yer değiştirmesi süreci.","Parçacık çapı küçüldükçe difüzyon katsayısı hızla artar; özellikle 0,1 µm altındaki nano parçacıklarda baskın taşıma mekanizmasıdır.","Solunum yolunun en derin bölgesi olan alveollerde nano parçacıkların doku yüzeylerine çarparak tutulmasını sağlar."],"tanim_en":"The net transport of ultrafine aerosol material driven by continuous random thermal collisions with surrounding air molecules.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S20"],"hesap":[]}},{"id":"coagulation","tr":"Pıhtılaşma","en":"coagulation","kisa":"","tur":"surec","es":["koagülasyon","topaklaşma"],"tanim":["Havada asılı küçük parçacıkların çarpışıp birleşerek daha büyük tek bir parçacık oluşturmasıdır.","Parçacık sayısı azalır, boyutu artar; toplam kütle değişmez.","Çekirdek modundaki parçacıkları birikme moduna taşıyan başlıca yoldur; kitapta 'pıhtılaşma', bazı kaynaklarda 'koagülasyon' ya da 'topaklaşma' denir."],"tanim_en":"Coagulation is the joining of small suspended particles into larger particles through collisions, which reduces particle number and grows size.","bag":{"kavram":["boyut-modlari"],"soru":[],"hesap":[]}},{"id":"nucleation","tr":"Çekirdeklenme (nükleasyon)","en":"nucleation","kisa":"","tur":"surec","es":["nükleasyon","yeni parçacık oluşumu","new particle formation"],"tanim":["Gaz fazından yeni parçacık doğma sürecidir; buhar, özel parçacıklar ('çekirdekler') üzerinde ya da kendiliğinden sıvı ya da katı faza geçer.","Atmosferde örneğin H₂SO₄ ve H₂O buharlarının bir araya gelmesiyle yeni parçacıklar oluşur; gazdan parçacığa dönüşümün ilk basamağıdır.","Parçacık sayısını artırır; gazdan dönüşen aerosollerin ince modda yer almasının nedenidir."],"tanim_en":"Nucleation is the formation of new particles from the vapour phase, in which a substance goes to the liquid or solid phase with or without the aid of special nuclei.","bag":{"kavram":["boyut-modlari"],"soru":["S14","S15","S17","S23"],"hesap":[]}},{"id":"cirrus","tr":"Sirrus","en":"cirrus","kisa":"Ci","tur":"kavram","es":["sirüs bulutu","siriform bulut","cirrus cloud","Ci"],"tanim":["Troposferin üst katmanlarında (genellikle > 5–7 km) bulunan, bütünüyle buz kristallerinden oluşan, lifsi ve ince yüksek bulut cinsi.","Bulut tepesi oldukça soğuktur (tipik 220 K); güneş albedosunu az artırırken yüzeyden gelen kızılötesi ışınımı kuvvetle tutar.","Geri yaydığı sera etkisi güneş yansıtma etkisini aştığı için Dünya yüzeyinde net ısınmaya yol açar."],"tanim_en":"A high atmospheric cloud composed of ice crystal particles that yields a net warming impact at the Earth surface.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":[]}},{"id":"high-cloud","tr":"Yüksek bulut","en":"high cloud","kisa":"","tur":"kavram","es":["yüksek seviye bulutu","high-level clouds","high-level cloud","üst seviye bulutu"],"tanim":["Troposferin üst katmanında (genellikle 5–7 km üzerinde) yer alan sirrus, sirrokümülüs ve sirrostratus bulutları grubu.","Bütünüyle buz kristallerinden meydana gelir ve tepe sıcaklığı yüzey sıcaklığına göre oldukça düşüktür.","Atmosfer modelinde ilave bir sera katmanı gibi davranarak uzaya giden uzun dalga ışınımı engeller ve yüzeyi net olarak ısıtır."],"tanim_en":"A cloud belonging to the upper tropospheric level that typically exerts a net warming influence on Earth surface.","bag":{"kavram":["bulut-isinim"],"soru":["S7","S10","S11","S12"],"hesap":[]}},{"id":"ice-crystal","tr":"Buz kristali","en":"ice crystal","kisa":"","tur":"kavram","es":["bulut buz parçacığı","atmospheric ice crystal","atmosferik buz kristali"],"tanim":["Üst troposferde ya da soğuk bulutlarda su buharının doğrudan donması veya aşırı soğumuş damlacıkların donmasıyla oluşan katı su parçacığı.","Sıcaklığa ve neme bağlı olarak altıgen prizma, levha veya iğne gibi çeşitli kristal geometrilerinde gelişir.","Sirrus bulutlarının temel yapı taşıdır; karışık fazlı bulutlarda buhar basıncı farkı nedeniyle aşırı soğumuş sıvı damlaların aleyhine hızla büyür."],"tanim_en":"A solid macroscopic particle of frozen water formed in the cold atmosphere that constitutes cirrus and mixed-phase cloud formations.","bag":{"kavram":["bulut-isinim"],"soru":[],"hesap":[]}},{"id":"low-cloud","tr":"Alçak bulut","en":"low cloud","kisa":"","tur":"kavram","es":["alçak seviye bulutu","low-level clouds","low-level cloud","alt seviye bulutu"],"tanim":["Tabanı genellikle 2 km altında yer alan, stratus ve stratokümülüs gibi sıvı su damlalarından oluşan bulut cinsi grubu.","Bulut tepe sıcaklığı yüzey sıcaklığına çok yakındır (tipik 280 K) ve uzaya kaçan kızılötesi ışınımı pek değiştirmez.","Güneş ışınımını yüksek albedosuyla uzaya geri yansıtarak Dünya yüzeyinde net soğutma etkisi meydana getirir."],"tanim_en":"A cloud situated below two kilometers altitude that reflects incoming solar radiation and cools the Earth surface.","bag":{"kavram":["bulut-isinim"],"soru":["S10","S11","S12"],"hesap":[]}},{"id":"mixed-phase-cloud","tr":"Karışık fazlı bulut","en":"mixed-phase cloud","kisa":"","tur":"kavram","es":["sıvı-buz karışık bulut","karışık bulut"],"tanim":["Sıvı su damlacıkları ile buz kristallerinin atmosferde aynı hava hacminde bir arada bulunduğu bulut türü.","Genellikle 0 °C ile yaklaşık −38 °C arasındaki sıcaklık aralığında varlığını sürdürür.","Buz üzerindeki doymuş buhar basıncı sıvı sudan daha düşük olduğundan buz kristalleri sıvı damlaların buharlaşmasıyla hızla büyür."],"tanim_en":"A cloud containing both supercooled liquid water droplets and ice crystal particles concurrently in the atmosphere.","bag":{"kavram":["bulut-isinim"],"soru":[],"hesap":[]}},{"id":"stratus","tr":"Stratus","en":"stratus","kisa":"St","tur":"kavram","es":["stratus bulutu","katman bulut","stratiform bulut","stratus cloud","St"],"tanim":["Yer yüzeyine yakın seviyede (< 2 km) tekdüze yatay bir tabaka oluşturan, gri renkli alçak bulut cinsi.","Tepe sıcaklığı yüzeye yakındır (tipik 280 K) ve optik olarak kalın yapısıyla güneş ışığını kuvvetle geri yansıtır.","Yüzeye yakın sıcaklıkta ışıma yaptığından sera etkisi zayıf kalır ve yüksek yansıtma oranıyla iklimi net olarak soğutur."],"tanim_en":"A low uniform grey cloud layer composed of liquid water droplets that strongly reflects sunlight and cools the surface.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":[]}},{"id":"warm-cloud","tr":"Sıcak bulut","en":"warm cloud","kisa":"","tur":"kavram","es":["yalnız sıvı bulut","sıvı fazlı bulut","liquid-only cloud"],"tanim":["Sıcaklığı donma noktasının (0 °C) üstünde olan ve bu yüzden yalnız sıvı su damlası içeren bulut; yükselen nemli havada yoğuşmayla oluşur.","Meteorolojide «sıcak» donma noktasının üstü demektir; bulut içinde buz kristali yoktur, yağış damlaların çarpışıp birleşmesiyle oluşur.","Kitapta karışık fazlı buluttan (sıvı + buz) ayırmak için kullanılır; ışınım hesabında alçak ve sıcak tepeli bulutlar bu gruba girer."],"tanim_en":"A warm cloud is a cloud at a temperature above 0 °C that therefore contains only liquid water droplets, formed by condensation in ascending moist air.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":[]}},{"id":"cloud-cover","tr":"Bulut örtüsü","en":"cloud cover","kisa":"","tur":"olcu","es":["bulut kapalılığı","bulutluluk","cloud fraction","cloud amount"],"tanim":["Gökyüzünün bulutla kaplı kesri; okta ya da yüzde olarak verilir. Model ve uydu dilinde aynı anlamda «cloud fraction» denir.","Gözlemle (okta) ya da uydu görüntüsünden hesaplanan boyutsuz bir kesirdir; bulutun kalınlığını ya da yüksekliğini göstermez.","Kitapta ısınmayla su buharı artınca örtünün nasıl değişeceği iklimin en büyük belirsizliği olarak ele alınır; örtü artarsa albedo artar ve soğutucu geri besleme beklenir."],"tanim_en":"Cloud cover is the fraction of the sky covered by clouds, expressed in oktas or as a percentage.","bag":{"kavram":["bulut-isinim"],"soru":["S12"],"hesap":["tek-katman"]}},{"id":"cloud-top-temperature","tr":"Bulut tepesi sıcaklığı","en":"cloud-top temperature","kisa":"T_tepe","tur":"olcu","es":["Ttepe","bulut tepe sıcaklığı","T_tepe","Tc"],"tanim":["Bulut tepesinin ya da o seviyeye yakın havanın sıcaklığı.","Kelvin cinsinden verilir; kitapta tipik değerler sirrus için 220 K, stratus için 280 K'dir. Opak bulut uzaya bu sıcaklıkta kara cisim gibi yayar: σT⁴.","Soğuk tepe (yüksek bulut) az yayar, yüzeyden gelen IR'nin çoğunu tutar ve ısıtır; sıcak tepe (alçak bulut) çok yayar ve az IR tutar."],"tanim_en":"Cloud-top temperature is the temperature of a cloud top or of the air near that level.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":["bulut-net"]}},{"id":"odd-oxygen","tr":"Tek oksijen","en":"odd oxygen","kisa":"","tur":"kavram","es":["Oₓ","odd-oxygen family","oksijen ailesi"],"tanim":["Atmosfer kimyasında hızlı birbirine dönüşen oksijen türlerini bir arada sayan aile; Oₓ simgesiyle gösterilir. «Odd» burada «tek» demektir.","Stratosferde Oₓ = O + O₃: R2 ve R3 O ile O₃'ü saniyeler içinde birbirine çevirir, toplam korunur. Kent havasında Oₓ = O₃ + NO₂ diye başka bir aile tanımlanır; bağlama bakmak gerekir.","Oₓ'i yalnız R1 üretir, R4 ve katalitik döngüler yok eder; stratosferde O₃ baskın olduğundan Oₓ pratikte O₃'tür."],"tanim_en":"Odd oxygen is the family of rapidly interconverting oxygen species, in the stratosphere O plus O₃, whose total is conserved by the fast cycling reactions.","bag":{"kavram":["chapman","titrasyon"],"soru":["S40","S41"],"hesap":[]}},{"id":"oxygen-atom","tr":"Oksijen atomu","en":"oxygen atom","kisa":"O","tur":"kavram","es":["O atomu","O(³P)","atomik oksijen","atomic oxygen"],"tanim":["Tek bir oksijen atomu, O; radikal gibi tepkimeye giren çok etkin bir türdür. «Oxygen molecule» O₂'dir.","Taban durum O(³P) ozon yapar (O + O₂ + M → O₃ + M); uyarılmış O(¹D) suyla OH üretir. Stratosferde çok kısa yaşar (30 km'de yaklaşık 0,03 s).","Kitapta O₃ fotolizinden (R3) ve O₂ fotolizinden (R1) oluşur; üst stratosferde bol bulunur. Troposferde NO₂ fotolizi O(³P) sağlayıp ozon üretimini başlatır."],"tanim_en":"An oxygen atom is a single oxygen atom, O, which in its ground state O(³P) combines with O₂ to form ozone and in its excited state O(¹D) reacts with water vapour to form OH.","bag":{"kavram":["chapman","psc","fotoliz"],"soru":["S40","S41"],"hesap":[]}},{"id":"ozone-layer","tr":"Ozon tabakası","en":"ozone layer","kisa":"","tur":"kavram","es":["stratosferik ozon tabakası","ozonosfer","iyi ozon"],"tanim":["Stratosferde O₃'ün en yoğun olduğu kuşak; kabaca 15–35 km arasındadır ve sayı yoğunluğu tepesi yaklaşık 20–25 km'de.","Toplam ozon sütunu ortalama yaklaşık 300 DU'dur. Karışım oranı yaklaşık 30–35 km'de en yüksektir (yaklaşık 8–10 ppm), mutlak molekül sayısı ise hava yoğunluğu aşağı doğru katlanarak arttığından daha alçakta zirve yapar.","Zararlı morötesi (UV-C ve büyük ölçüde UV-B) ışınımı soğurur. Yer seviyesindeki ozon ayrı bir olgudur ve kirleticidir: «iyi ozon – kötü ozon» ayrımı."],"tanim_en":"The ozone layer is the region of the stratosphere, roughly 15 to 35 km above the surface, where ozone concentration is greatest and which absorbs most harmful ultraviolet radiation.","bag":{"kavram":["chapman"],"soru":["S1"],"hesap":[]}},{"id":"monsoon","tr":"Muson","en":"monsoon","kisa":"","tur":"kavram","es":["muson dolaşımı","monsoon circulation","muson rüzgârları","Asya musonu","muson yağışları","muson rüzgârı"],"tanim":["Genel dolaşımda mevsimsel kalıcı rüzgâr yönüyle ve bir mevsimden ötekine belirgin yön değişimiyle tanınan rüzgâr. Ana nedeni kara ile komşu okyanusun mevsime göre değişen ısınma farkıdır.","Yön değişimine geniş çaplı sıcaklık ve yağış değişimleri eşlik eder; özellikle yarı tropik bölgelerde yaz musonu yağışının ana kaynağıdır.","Kitapta volkanik soğumanın dolaşıma etkisi olarak geçer: deniz soğuyunca buharlaşma azalır, Hadley hücresi zayıflar ve muson yağışı düşer."],"tanim_en":"A monsoon is a seasonally persistent wind that changes direction markedly from one season to another, driven mainly by the differential heating between a continent and the adjacent ocean.","bag":{"kavram":["clausius","volkan-aerosol"],"soru":["S33"],"hesap":[]}},{"id":"relative-humidity","tr":"Bağıl nem","en":"relative humidity","kisa":"RH","tur":"olcu","es":["nisbi nem","oransal nem","RH","göreli nem"],"tanim":["Havadaki buhar basıncının, aynı sıcaklık ve basınçta doymuş buhar basıncına oranı yüzde olarak: RH = e / eₛ × 100 (%).","Boyutsuzdur ve havadaki buhar miktarının kendisi değildir; sıcaklık artınca eₛ arttığı için aynı buhar miktarında RH düşer.","Kitapta ısınmayla eₛ yaklaşık %7/K arttığında RH kabaca sabit kalırsa buharın da aynı oranda artacağı, bunun da en güçlü pozitif geri beslemeyi (su buharı) verdiği kullanılır."],"tanim_en":"Relative humidity is the ratio, expressed as a percentage, of the actual vapour pressure of the air to the saturation vapour pressure at the same temperature and pressure.","bag":{"kavram":["clausius","geri-besleme"],"soru":["S11","S13"],"hesap":["zorlama"]}},{"id":"saturation-vapour-pressure","tr":"Doymuş buhar basıncı","en":"saturation vapour pressure","kisa":"eₛ","tur":"olcu","es":["es","es(T)","doyma buhar basıncı","denge buhar basıncı","eₛ","eₛ(T)"],"tanim":["Düz su yüzeyi üstünde buharın sıvıyla dengede olduğu basınçtır; yalnız sıcaklığa bağlıdır.","Birimi hPa; 15 °C'de ≈ 17,0 hPa. Sıcaklık her 1 K arttığında ≈ %7 büyür (üstel artış).","Hava eₛ'den fazla buhar taşıyamaz, fazlası yoğuşur. Bağıl nem RH = e/eₛ ile bulunur; LCL ve su buharı geri beslemesinde eₛ(T) belirleyicidir."],"tanim_en":"Saturation vapour pressure is the pressure of water vapour in equilibrium with a plane surface of liquid water at a given temperature.","bag":{"kavram":["clausius"],"soru":["S4","S13","S15","S19","S33","S34"],"hesap":["clausius"]}},{"id":"vapour-pressure","tr":"Buhar basıncı","en":"vapour pressure","kisa":"e","tur":"olcu","es":["kısmi buhar basıncı","water vapour pressure","su buharı basıncı","vapor pressure","e"],"tanim":["Havadaki su buharının kısmi basıncıdır (e); toplam basıncın yalnız buhar payıdır.","Birimi hPa; bağıl nem RH = e/eₛ ile bulunur. Buhar miktarı korunurken basınç düşerse e de azalır.","Kitapta yükselen parselde çiy noktasının ≈ 1,8 K/km düşmesini ve LCL hesabını anlamak için kullanılır; ısınma sorusunda e ile eₛ(T) karşılaştırılır."],"tanim_en":"Vapour pressure is the partial pressure exerted by water vapour in a mixture of air and water vapour.","bag":{"kavram":["clausius","lcl"],"soru":["S13","S33"],"hesap":["clausius"]}},{"id":"magnus-formula","tr":"Magnus formülü","en":"Magnus formula","kisa":"eₛ(T)","tur":"yontem","es":["Magnus-Tetens bağıntısı","Magnus denklemi","Magnus equation","Magnus-Tetens formula"],"tanim":["Doymuş buhar basıncını sıcaklığın fonksiyonu olarak veren ampirik bağıntıdır: eₛ = 6,112 exp[17,67 T/(T + 243,5)] hPa.","Bağıntıda T Celsius cinsindendir; T'yi kelvin yazmak sık yapılan hatadır. Sonuç hPa çıkar.","Clausius–Clapeyron denkleminin integraline uydurulmuş bir yaklaşımdır; kitapta ısınmadan sonra eₛ'nin yüzde artışını hesaplamak için kullanılır."],"tanim_en":"The Magnus formula is an empirical expression that gives saturation vapour pressure over liquid water as an exponential function of temperature in degrees Celsius.","bag":{"kavram":["clausius"],"soru":["S13"],"hesap":["clausius"]}},{"id":"anomaly","tr":"Anomali","en":"anomaly","kisa":"","tur":"kavram","es":["normalden sapma","sapma","departure from the mean","deviation"],"tanim":["Bir değerin uzun dönem ortalamasından (iklimsel normalinden) farkıdır; işareti olan sayısal bir fark.","Birimi büyüklüğün kendi birimidir (°C, hPa); standartlaştırılırsa boyutsuz olur. Güney Salınımı indeksi (SOI) tipik −2…+2 aralığında standartlaştırılmış basınç farkı anomalisidir.","Kitapta ENSO fazını belirlemek için kullanılır; deniz yüzeyi sıcaklığı anomalisi pozitifse El Niño, negatifse La Niña. 'Anormal' sözcüğüyle karıştırılmamalı."],"tanim_en":"An anomaly is the departure of a value of a variable from its long-term average for the same location and time of year.","bag":{"kavram":["enso"],"soru":["S35"],"hesap":[]}},{"id":"el-nino","tr":"El Niño","en":"El Niño","kisa":"","tur":"kavram","es":["El Nino olayı","sıcak ENSO fazı","sıcak faz","El Niño olayı","ENSO sıcak evresi","warm phase of ENSO"],"tanim":["Doğu ve orta tropik Pasifik'te deniz yüzeyinin normalden sıcak olduğu ENSO evresidir; atmosferdeki eşi negatif Güney Salınımıdır.","NOAA ölçütü Niño 3.4 bölgesinde 3 aylık ortalama SST anomalisinin ≥ +0,5 °C olmasıdır (ONI). Tahiti − Darwin basınç farkı azalır, SOI negatif olur.","Kitapta mekanizma şöyle kurulur: ticaret rüzgârları zayıflar, sıcak su doğuya yayılır, yağış doğuya kayar; Peru'da sel, Endonezya ve Avustralya'da kuraklık görülür."],"tanim_en":"El Niño is the warm phase of the El Niño–Southern Oscillation, in which sea surface temperatures in the central and eastern tropical Pacific are above normal.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"la-nina","tr":"La Niña","en":"La Niña","kisa":"","tur":"kavram","es":["La Nina olayı","soğuk ENSO fazı","soğuk faz","La Niña olayı","ENSO soğuk evresi","cold phase of ENSO"],"tanim":["Doğu ve orta tropik Pasifik'te deniz yüzeyinin normalden soğuk olduğu ENSO evresidir; El Niño'nun tersidir.","NOAA ölçütü Niño 3.4 bölgesinde 3 aylık SST anomalisinin ≤ −0,5 °C olmasıdır. Kitaba göre 2–7 yılda bir görülür ve 9–12 ay sürer.","Ticaret rüzgârları normalden güçlüdür, doğuda soğuk su yükselimi artar; Peru daha kurak, Endonezya daha yağışlı olur. El Niño'yu 'soğuma' sanmak tipik hatadır."],"tanim_en":"La Niña is the cold phase of the El Niño–Southern Oscillation, in which sea surface temperatures in the central and eastern tropical Pacific are below normal.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"thermocline","tr":"Termoklin","en":"thermocline","kisa":"","tur":"kavram","es":["termoklin katmanı","sıcaklık sıçrama tabakası","termoklin tabakası","oceanic thermocline"],"tanim":["Okyanusta sıcaklığın derinlikle hızla düştüğü, sıcaklık gradyanının en büyük olduğu tabakadır.","Üstte sıcak karışık tabaka, altında soğuk derin su bulunur; derinliği metre cinsinden verilir ve bölgeye göre değişir.","Normalde doğu Pasifik'te sığdır, bu yüzden soğuk su yükselebilir. El Niño'da doğuda derinleşir; yükselen su artık sıcaktır ve besin getirmez."],"tanim_en":"The thermocline is the layer of a thermally stratified body of water across which the temperature gradient is at a maximum.","bag":{"kavram":["enso"],"soru":["S35"],"hesap":[]}},{"id":"trade-winds","tr":"Ticaret rüzgârları","en":"trade winds","kisa":"","tur":"kavram","es":["alize rüzgârları","alizeler","ticaret rüzgârı","trades","trade wind"],"tanim":["Subtropikal yüksek basınç merkezlerinden ekvatora doğru esen sürekli alçak seviye rüzgârlardır; Kuzey Yarıküre'de kuzeydoğulu, Güney'de güneydoğulu.","Tropik Pasifik'te doğudan batıya eser ve yüzeydeki sıcak suyu batıya iter. Türkçe meteorolojide 'alize' daha yaygındır; kitap 'ticaret rüzgârları' der.","ENSO'nun anahtarıdır; El Niño'da zayıflar (sıcak su doğuya yayılır), La Niña'da güçlenir (doğuda soğuk su yükselimi artar)."],"tanim_en":"Trade winds are persistent winds in the lower atmosphere that blow from the subtropical anticyclones towards the equatorial regions, from the north-east in the Northern Hemisphere and from the south-east in the Southern Hemisphere.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"walker-circulation","tr":"Walker dolaşımı","en":"Walker circulation","kisa":"","tur":"kavram","es":["Walker hücresi","Walker dolaşım hücresi","Walker cell","doğu–batı Pasifik dolaşımı"],"tanim":["Ekvator Pasifik'inde ısıyla yönlenen doğu–batı dolaşım hücresi: sıcak batıda (Endonezya) hava yükselir, soğuk doğuda çöker.","Alt düzeyde ticaret rüzgârları doğudan batıya eser; yükselme bölgesinde bulut ve yağış oluşur. Hadley hücresi ise kuzey–güney yönlüdür.","Kitapta ENSO'nun atmosfer kolu olarak geçer; El Niño sırasında zayıflar, Tahiti–Darwin basınç farkı da bu değişimi izler."],"tanim_en":"The Walker circulation is a direct, thermally driven zonal circulation of the tropical Pacific in which air goes up over the warm western Pacific and sinks over the cold eastern Pacific.","bag":{"kavram":["enso"],"soru":[],"hesap":[]}},{"id":"sea-surface-temperature","tr":"Deniz yüzeyi sıcaklığı","en":"sea surface temperature","kisa":"SST","tur":"olcu","es":["deniz suyu sıcaklığı","deniz yüzey sıcaklığı","SST","deniz yüzey suyu sıcaklığı","DYS","okyanus yüzey sıcaklığı"],"tanim":["Okyanusun üst birkaç metresinin sıcaklığıdır (SST).","Birimi °C ya da K; uydu ve şamandıra ölçümleriyle izlenir. ENSO evresi SST anomalisinin işaretiyle belirlenir.","Buharlaşmayı ve atmosfere giden nem miktarını belirler; soğuk deniz daha az buharlaşır. Kitapta hem El Niño hem Pinatubo sonrası soğumada anahtar değişkendir."],"tanim_en":"Sea surface temperature is the temperature of the upper few metres of the ocean.","bag":{"kavram":["enso","volkan-aerosol"],"soru":["S33","S35"],"hesap":["sonum"]}},{"id":"upwelling","tr":"Soğuk su yükselimi","en":"upwelling","kisa":"","tur":"surec","es":["derin su yükselimi","kıyı yükselimi","yükselim","su yükselimi","coastal upwelling"],"tanim":["Derindeki soğuk ve besin tuzlarınca zengin suyun yüzeye çıkmasıdır.","Peru kıyısında ticaret rüzgârlarının yüzey suyunu açığa itmesiyle olur; yüzeyi soğutur ve plankton ile balık üretimini besler.","El Niño'da rüzgârlar zayıflar, termoklin derinleşir ve sıcak yüzey suyu yükselimi bastırır; balık azalır. La Niña'da yükselim artar."],"tanim_en":"Upwelling is the vertical movement of cold, nutrient-rich water from depth towards the ocean surface.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"photoionization","tr":"Fotoiyonlaşma","en":"photoionization","kisa":"","tur":"kavram","es":["foto-iyonlaşma","photoionisation","ışıkla iyonlaşma"],"tanim":["Bir fotonun molekülden ya da atomdan elektron koparması: AB + hν → AB⁺ + e⁻.","Çok kısa dalga boyu gerekir (≲ 100 nm; uç morötesi, X ışını); bu yüzden yalnız yüksek atmosferde olur.","Kitapta iyonosferi (≈ 60 km üstü) oluşturan süreçtir; ozon kimyasının parçası değildir."],"tanim_en":"Photoionization is the process in which a photon ejects an electron from an atom or molecule, leaving a positively charged ion.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":[]}},{"id":"absorption-cross-section","tr":"Soğurma kesiti","en":"absorption cross section","kisa":"σₐ","tur":"olcu","es":["soğurma tesir kesiti","absorpsiyon kesiti","σ (fotoliz)"],"tanim":["Bir molekülün ya da parçacığın belirli dalga boyunda fotonu yakalama 'alanı'; simgesi σₐ (fotolizde σ), birimi cm².","Beer–Lambert yasasında τ = (σₛ + σₐ) n L ile optik derinliğe girer; saçılma kesiti σₛ ile toplanıp yok olma katsayısı K = (σₛ + σₐ) n verir.","Fotolizde σ(λ) J integralinde yer alır; aerosolde σₐ büyükse (is gibi koyu parçacık) tek saçılma albedosu ω küçülür. Stefan–Boltzmann sabiti σ ile aynı harftir, birime bakılmalıdır."],"tanim_en":"The absorption cross section is the effective area, in cm², of a molecule or particle for absorbing photons of a given wavelength.","bag":{"kavram":["fotoliz","beer-lambert","aerosol-dogrudan"],"soru":["S24","S25","S40"],"hesap":["beer-kesit"]}},{"id":"actinic-flux","tr":"Aktinik akı","en":"actinic flux","kisa":"F(λ)","tur":"olcu","es":["aktinik ışınım akısı","küresel aktinik akı","actinic radiation flux","spherical irradiance"],"tanim":["Bir noktaya her yönden gelen fotonların toplamı; birimi foton cm⁻² s⁻¹ nm⁻¹.","Molekül ışığı yönden bağımsız soğurduğu için fotolizde yatay yüzeye gelen ışınım (irradiance) değil aktinik akı kullanılır.","Kitapta F(λ) simgesiyle J integralinde σ(λ) ve φ(λ) ile çarpılır; güneş yüksekken büyük, gece sıfırdır."],"tanim_en":"Actinic flux is the total number of photons per unit area, time and wavelength arriving at a point from all directions, which is the quantity that drives photolysis.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"bond-dissociation-energy","tr":"Bağ ayrışma enerjisi","en":"bond dissociation energy","kisa":"D","tur":"olcu","es":["bağ entalpisi","bağ koparma enerjisi","bond energy","bağ enerjisi"],"tanim":["Bir kimyasal bağı koparmak için gereken enerji; birimi kJ/mol.","Foton enerjisiyle karşılaştırılarak eşik dalga boyu bulunur: λ_max = hcN_A/D. O₂ için 498 kJ/mol → 240 nm; O₃ için 105 kJ/mol → 1140 nm.","Hangi molekülün hangi dalga boyunda fotolize uğrayacağını belirler; O₂ yalnız çok kısa dalgada, O₃ görünür dalgaya yakın bölgede bölünür."],"tanim_en":"Bond dissociation energy is the energy required to break a specified chemical bond, usually expressed in kJ/mol.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"photolysis-frequency","tr":"Fotoliz frekansı","en":"photolysis frequency","kisa":"J","tur":"olcu","es":["fotoliz hızı","fotoliz katsayısı","J sembolü","fotoliz hız katsayısı","J katsayısı","fotoliz hız sabiti"],"tanim":["Birim zamanda foton soğurarak bölünen molekül kesri; simgesi J, birimi s⁻¹ (birinci mertebe hız sabiti).","J = ∫ σ(λ) φ(λ) F(λ) dλ; hız = J[AB], ömür τ = 1/J. Gece sıfırdır.","NO₂ için öğlen J ≈ 8 × 10⁻³ s⁻¹ olduğundan τ = 125 s ≈ 2 dk; kitapta Chapman ve fotodurağan denge hesaplarında kullanılır."],"tanim_en":"The photolysis frequency is the first-order rate coefficient (in s⁻¹) for the photodissociation of a molecule, equal to the fraction of molecules photolysed per unit time.","bag":{"kavram":["fotoliz"],"soru":["S40","S41","S44"],"hesap":["fotoliz","chapman-o","leighton"]}},{"id":"quantum-yield","tr":"Kuantum verimi","en":"quantum yield","kisa":"φ(λ)","tur":"olcu","es":["bölünme verimi","kuantum etkinliği","kuantum randımanı","quantum efficiency","φ"],"tanim":["Soğurulan bir fotonun belirli bir ürünü (ör. bölünmeyi) verme olasılığı; simgesi φ, değeri 0–1 arasındadır.","Birimsizdir ve dalga boyuna bağlıdır, φ(λ). φ < 1 ise soğurulan fotonların bir kısmı ısıya ya da ışımaya gider.","Kitapta J integralinde σ(λ) ve aktinik akı F(λ) ile çarpılan üçüncü çarpandır."],"tanim_en":"Quantum yield is the number of molecules undergoing a given photochemical event per photon absorbed, a dimensionless quantity between 0 and 1.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"solar-zenith-angle","tr":"Güneş zenit açısı","en":"solar zenith angle","kisa":"θ","tur":"olcu","es":["zenit açısı","güneş başucu açısı","başucu","Zenit","zenith","zenith angle"],"tanim":["Güneşin tepe (zenit) doğrultusundan açısı; 0° tam tepede demektir. Güneş yükseklik açısı 90° − θ'dır.","Işığın atmosferdeki yolu ≈ 1/cos θ kat uzar (hava kütlesi): 60° → 2 kat, 80° → 5,8 kat. θ ≳ 75°'te Dünya'nın eğriliği önem kazanır.","θ büyüdükçe geçen ışık, J ve yüzeyin ısınması azalır; kitapta Beer–Lambert eğik ışın hesabında kullanılır."],"tanim_en":"The solar zenith angle is the angle between the local vertical (zenith) and the direction to the centre of the Sun.","bag":{"kavram":["fotoliz","beer-lambert"],"soru":["S24"],"hesap":["egik-isin"]}},{"id":"threshold-wavelength","tr":"Eşik dalga boyu","en":"threshold wavelength","kisa":"λ_max","tur":"olcu","es":["eşik dalga boyu λ_max","kesim dalga boyu","photodissociation threshold"],"tanim":["Bir bağı koparabilen en uzun dalga boyu; daha uzun dalganın fotonu (düşük enerji) bağı koparamaz.","λ_max = hcN_A/D; birimi nm. O₂ için ≈ 240 nm, O₃ için ≈ 1140 nm.","Kitapta hangi ışığın hangi molekülü böleceğini gösterir; O₂ yalnız morötesinde, O₃ görünür ve yakın kızılötesinde bölünür."],"tanim_en":"The threshold wavelength is the longest wavelength of radiation whose photons carry enough energy to break a given chemical bond.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"cloud-feedback","tr":"Bulut geri beslemesi","en":"cloud feedback","kisa":"","tur":"kavram","es":["bulut geri bildirimi","cloud radiative feedback"],"tanim":["Isınmayla bulut örtüsü, yüksekliği ve kalınlığının değişmesi ve bunun ışınım dengesini yeniden etkilemesi; ısınmayı artırırsa pozitif, azaltırsa negatiftir.","Bulutun net ışınım etkisi ΔF_net (W/m²) ile gösterilir; + ısıtır, − soğutur. Yüksek bulut ısıtma, alçak bulut soğutma eğiliminde.","İşareti ve büyüklüğü belirsizdir; iklim tahmininin en büyük belirsizlik kaynağıdır (IPCC AR6: büyük olasılıkla küçük pozitif)."],"tanim_en":"Cloud feedback is the change in the climate system's radiative balance caused by cloud changes that are themselves a response to surface warming.","bag":{"kavram":["geri-besleme","bulut-isinim"],"soru":["S9","S12"],"hesap":[]}},{"id":"negative-feedback","tr":"Negatif geri besleme","en":"negative feedback","kisa":"(−)","tur":"kavram","es":["olumsuz geri besleme","dengeleyici geri besleme","damping feedback"],"tanim":["İlk değişikliği küçülten ve sistemi dengeye çeken geri besleme; ısınma sonucunda ortaya çıkan bir süreç ısınmayı frenler.","İklim geri besleme çarpanı f negatif ya da küçük olduğunda toplam ısınma ΔT, geri beslemesiz ısınma ΔT₀'dan küçük kalır.","Temel örnek Planck tepkisidir; sıcak yüzey σT⁴ ile daha çok yayar. Kitapta alçak bulutlar (stratus) da güneşi yansıtıp ısınmayı frenleyen bir negatif geri besleme olarak ele alınır."],"tanim_en":"A negative feedback is a process in which an initial change triggers a response that reduces that change and stabilizes the system.","bag":{"kavram":["geri-besleme","bulut-isinim"],"soru":["S8","S10","S12","S13"],"hesap":[]}},{"id":"positive-feedback","tr":"Pozitif geri besleme","en":"positive feedback","kisa":"(+)","tur":"kavram","es":["olumlu geri besleme","büyütücü geri besleme","amplifying feedback"],"tanim":["İlk değişikliği büyüten geri besleme; bir zorlamanın yarattığı ısınmayı başka bir değişken aracılığıyla daha da artırır.","İklim geri besleme çarpanı f pozitif olduğunda ΔT = ΔT₀ / (1 − f) ifadesi ΔT₀'dan büyük çıkar; f → 1 olursa ısınma sınırsız büyür.","«Pozitif» iyi anlamına gelmez; su buharı ve buz–albedo geri beslemeleri ısınmayı artıran pozitif geri beslemelerdir."],"tanim_en":"A positive feedback is a process in which an initial change triggers a response that amplifies that change and moves the system further from its starting state.","bag":{"kavram":["geri-besleme"],"soru":["S8","S9","S10","S12","S13"],"hesap":[]}},{"id":"water-vapour-feedback","tr":"Su buharı geri beslemesi","en":"water vapour feedback","kisa":"","tur":"kavram","es":["su buharı geri bildirimi","water vapor feedback","su buharı geribeslemesi"],"tanim":["Isınmanın atmosferdeki su buharını artırması ve artan buharın daha çok kızılötesi tutarak ısınmayı güçlendirmesi.","Doymuş buhar basıncı Clausius–Clapeyron ilişkisine göre her 1 K'de yaklaşık %7 artar; bağıl nem kabaca sabit kalırsa buhar aynı oranda artar.","En güçlü pozitif iklim geri beslemesidir. Su buharı doğrudan insan salımıyla birikmediği için zorlama değil, geri besleme sayılır."],"tanim_en":"Water vapour feedback is the amplification of warming that occurs because a warmer atmosphere holds more water vapour, a greenhouse gas that absorbs additional infrared radiation.","bag":{"kavram":["geri-besleme","clausius"],"soru":["S9","S13"],"hesap":[]}},{"id":"sym-feedback-gain","tr":"Geri besleme çarpanı","en":"feedback factor","kisa":"f","tur":"olcu","es":["geri besleme kazancı","feedback gain","f çarpanı"],"tanim":["f: iklim sisteminin toplam geri besleme kazancı; boyutsuz bir sayıdır ve su buharı, buz–albedo ile bulut katkılarının toplamıdır.","λ = λ₀ / (1 − f) ilişkisinden f = 1 − λ₀/λ bulunur; ΔT/ΔT₀ oranı da geri besleme kazancını verir. Kitaptaki değerler λ₀ = 0,27 ve λ = 0,8 için f ≈ 0,67 çıkar.","f → 1 olursa ısınma sınırsız büyür; f negatifse geri besleme ısınmayı küçültür."],"tanim_en":"The feedback factor f is the dimensionless net gain of climate feedbacks, defined by ΔT = ΔT₀ / (1 − f), so that f approaching 1 implies runaway warming.","bag":{"kavram":["geri-besleme"],"soru":["S9"],"hesap":["zorlama"]}},{"id":"ice-albedo-feedback","tr":"Buz–albedo geri beslemesi","en":"ice–albedo feedback","kisa":"","tur":"surec","es":["kar-buz albedo geri beslemesi","albedo geri beslemesi","kar/buz–albedo geri beslemesi","snow-ice albedo feedback"],"tanim":["Isınmanın kar ve buzu eritip yüzeyi koyulaştırması, albedoyu düşürmesi ve daha çok güneş ışınımının soğurulmasıyla ısınmayı artırması.","Zincir şöyledir: ısınma → kar ve buz erir → albedo azalır → soğurulan güneş ışınımı artar → daha çok ısınma.","Pozitif bir geri beslemedir; kar ve buzun çok olduğu kutup bölgelerinde özellikle güçlüdür."],"tanim_en":"Ice–albedo feedback is the amplification of warming caused by melting snow and ice, which lowers the surface albedo so that more solar radiation is absorbed.","bag":{"kavram":["geri-besleme"],"soru":[],"hesap":[]}},{"id":"planck-feedback","tr":"Planck geri beslemesi","en":"Planck feedback","kisa":"","tur":"surec","es":["Planck soğuma geri beslemesi","Planck response","Planck tepkisi"],"tanim":["Isınan yüzeyin ve atmosferin Stefan–Boltzmann yasasına göre σT⁴ ile daha çok ışınım yayması; ısınmayı sınırlayan temel negatif geri besleme.","Geri beslemesiz duyarlılık λ₀ = 1/(4σTₑ³) ≈ 0,27 K/(W m⁻²) buradan gelir; Tₑ ≈ 255 K alınır.","Kitapta öteki geri beslemeler Planck tepkisinin üstüne eklenir; tek başına CO₂ ikiye katlanınca yaklaşık 1 K ısınma verir."],"tanim_en":"The Planck feedback is the increase in outgoing longwave emission, proportional to T⁴, that accompanies surface and atmospheric warming and thereby acts as the fundamental stabilizing response of the climate system.","bag":{"kavram":["geri-besleme","zorlama"],"soru":["S9"],"hesap":[]}},{"id":"unit-micrometer","tr":"Mikrometre","en":"micrometre","kisa":"µm","tur":"birim","es":["mikron","micron","micrometer","Micrometer","µm"],"tanim":["Uzunluk birimi; 1 µm = 10⁻⁶ m = 10⁻³ mm.","Kızılötesi dalga boylarını (Dünya ışınımı ≈ 10 µm) ve aerosol parçacık çaplarını (PM2.5 ve PM10) ifade etmek için kullanılır.","Kitapta soğurma bantlarını (15 µm CO₂), aerosol boyut modlarını ve PM sınırlarını (2,5 µm, 10 µm) göstermek için kullanılır."],"tanim_en":"The micrometre (µm) is a unit of length equal to one millionth of a metre, commonly used for infrared wavelengths and aerosol particle diameters.","bag":{"kavram":["ir-aktif","boyut-modlari","pm"],"soru":["S5","S14","S15","S16","S17","S19"],"hesap":[]}},{"id":"absorption-band","tr":"Soğurma bandı","en":"absorption band","kisa":"","tur":"kavram","es":["soğurma şeridi"],"tanim":["Bir molekülün ışınımı güçlü soğurduğu dalga boyu aralığı; moleküllerin titreşim ve/veya dönme enerji düzeyleri artar.","Kitapta bant şiddeti I, dipol momentinin titreşim koordinatına göre değişiminin karesiyle orantılıdır (N₂ için 0).","CO₂'nin 15 µm bandının merkezi doymuştur; ek CO₂ bant kanatlarında soğurur, bu yüzden zorlama logaritmik artar."],"tanim_en":"An absorption band is a range of wavelengths over which molecules strongly absorb radiation, raising their vibrational and/or rotational energy states.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"asymmetric-stretch","tr":"Asimetrik gerilme","en":"asymmetric stretch","kisa":"ν₃","tur":"kavram","es":["asimetrik gerilme kipi","asimetrik esneme","antisymmetric stretching","asymmetric stretching","ν₃"],"tanim":["Üç atomlu bir molekülde bir bağ uzarken öteki kısalan titreşim kipi; sembolü ν₃.","CO₂'de iki O aynı yöne, C ters yöne kayar; dipol momenti salındığı için kip IR aktiftir ve 4,3 µm'de güçlü soğurma verir.","Kitapta CO₂'nin üç titreşiminden biridir; simetrik gerilme IR aktif değildir, bükülme (15 µm) ise aktiftir."],"tanim_en":"The asymmetric stretch is a vibrational mode of a triatomic molecule in which one bond lengthens while the other shortens, producing an oscillating dipole in CO₂ that absorbs at 4.3 µm.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"atmospheric-window","tr":"Pencere bölgesi","en":"atmospheric window","kisa":"8–12 µm","tur":"kavram","es":["atmosferik pencere","IR penceresi","infrared window","atmosfer penceresi"],"tanim":["Atmosferin yeryüzünden yayılan uzun dalga ışınımı çok az soğurduğu spektral bölge.","Kitapta 8–12 µm aralığıdır; H₂O ve CO₂ burada zayıf soğurur, yüzey IR'si doğrudan uzaya kaçabilir.","Bu aralıkta soğuran O₃ (9,6 µm) ve CFC'ler molekül başına çok etkili sera gazlarıdır."],"tanim_en":"An atmospheric window is a spectral region in which the atmosphere absorbs very little terrestrial radiation, allowing it to escape to space.","bag":{"kavram":["ir-aktif","tek-katman"],"soru":[],"hesap":[]}},{"id":"molecular-nitrogen","tr":"Azot gazı","en":"molecular nitrogen","kisa":"N₂","tur":"kavram","es":["moleküler azot","diatomik azot","dinitrogen","nitrogen gas","N2","N₂"],"tanim":["Azot atomlarının üçlü bağla bağlandığı simetrik iki atomlu moleküldür (N₂); kuru havanın hacimce yaklaşık %78'ini oluşturur.","Simetrik olduğu için titreşirken dipol momenti hep sıfır kalır (∂μ/∂Q = 0); bu yüzden kızılötesi (IR) fotonu soğurmaz.","Sera etkisine katkı vermez; kimyada ise üç cisimli tepkimelerde fazla enerjiyi alan çarpışma ortağı M olarak görev yapar."],"tanim_en":"Molecular nitrogen (N₂) is the symmetric diatomic molecule that makes up about 78 % of dry air by volume and is not infrared-active.","bag":{"kavram":["ir-aktif","asit-yagmuru"],"soru":["S5","S22"],"hesap":["twomey"]}},{"id":"molecular-oxygen","tr":"Oksijen gazı","en":"molecular oxygen","kisa":"O₂","tur":"kavram","es":["moleküler oksijen","diatomik oksijen","dioxygen","oxygen gas","O2","Moleküler oksijen"],"tanim":["İki oksijen atomundan oluşan simetrik iki atomlu moleküldür (O₂); kuru havanın hacimce yaklaşık %21'idir.","Simetrik olduğundan IR aktif değildir; ama 240 nm'den kısa dalga boylu morötesi fotonla bölünür (O₂ + hν → 2 O).","Oluşan O atomu O₂ ile ve üçüncü cisimle birleşerek ozonu yapar; ozonun katalitik ve titrasyon tepkimelerinde de O₂ ürün olarak çıkar."],"tanim_en":"Molecular oxygen (O₂) is the diatomic molecule that makes up about 21 % of dry air, is infrared-inactive, and is photolysed by short-wave ultraviolet radiation to start ozone formation.","bag":{"kavram":["ir-aktif","asit-yagmuru","volkan-aerosol"],"soru":["S5","S32","S40","S41","S42","S43"],"hesap":["chapman-o"]}},{"id":"permanent-dipole","tr":"Kalıcı dipol","en":"permanent dipole","kisa":"μ₀","tur":"kavram","es":["kalıcı dipol momenti","permanent dipole moment","μ₀"],"tanim":["Bir molekülün denge geometrisinde var olan, titreşimden bağımsız sabit dipol momentidir (μ₀).","Sabit bir sayı olduğundan farklı titreşim durumları arasında geçiş vermez: ⟨v'|μ₀|v⟩ = μ₀⟨v'|v⟩ = 0 (v' ≠ v).","IR soğurma için ölçüt kalıcı dipol değil, titreşimle dipolün değişmesidir; CO₂'nin kalıcı dipolü yoktur ama IR aktiftir."],"tanim_en":"A permanent dipole is the fixed electric dipole moment a molecule has at its equilibrium geometry, which by itself cannot cause infrared absorption because it does not change during vibration.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"photon","tr":"Foton","en":"photon","kisa":"hν","tur":"kavram","es":["ışık kuantumu","light quantum","hν"],"tanim":["Elektromanyetik ışınımın enerji paketidir (kuantumu); enerjisi E = hν = hc/λ ile verilir.","Kısa dalga boylu foton yüksek enerjilidir; fotolizde tek bir fotonun enerjisi bağ enerjisini aşmalıdır, düşük enerjili fotonlar toplanmaz.","Kitapta IR fotonu titreşim geçişini, UV ve görünür foton ise NO₂, O₂, O₃ gibi moleküllerin fotolizini (hν) başlatır."],"tanim_en":"A photon is the quantum of electromagnetic radiation, carrying energy E = hν = hc/λ, which can be absorbed by a molecule to excite it or to break a bond.","bag":{"kavram":["ir-aktif","psc","fotoliz"],"soru":["S5","S21","S32","S40","S41","S42"],"hesap":["fotoliz","chapman-o","leighton"]}},{"id":"symmetric-stretch","tr":"Simetrik gerilme","en":"symmetric stretch","kisa":"ν₁","tur":"kavram","es":["simetrik gerilme kipi","simetrik esneme","symmetric stretching","ν₁"],"tanim":["İki bağın aynı anda uzayıp kısaldığı titreşim kipidir (ν₁).","CO₂'de iki O eşit uzaklaştığı için toplam dipol her an sıfır kalır; bu kip IR aktif değildir.","Bu nedenle CO₂'nin 4,3 µm ve 15 µm bantlarına katkı vermez; yalnız asimetrik gerilme ve bükülme soğurur."],"tanim_en":"The symmetric stretch is the vibrational mode in which bonds lengthen and shorten in phase, so in CO₂ the dipole moment stays zero and the mode is infrared-inactive.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"vibrational-mode","tr":"Titreşim kipi","en":"vibrational mode","kisa":"","tur":"kavram","es":["titreşim modu","molekül titreşimi","titreşim","moleküler titreşim","molecular vibration"],"tanim":["Molekülün atomlarının belirli bir düzenle birlikte salındığı titreşim biçimidir (kip).","CO₂'nin üç kipi vardır: simetrik gerilme, asimetrik gerilme ve iki katlı bükülme; her kipin titreşim koordinatı Q ile tanımlanır.","Bir kip yalnız titreşim sırasında elektrik dipol momenti değişiyorsa IR fotonu soğurur (seçim kuralı); ortak ölçüt budur."],"tanim_en":"A vibrational mode is a characteristic pattern of coordinated atomic motion in a molecule, and it absorbs infrared radiation only if the motion changes the molecule's electric dipole moment.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"dipole-moment","tr":"Dipol moment","en":"dipole moment","kisa":"μ","tur":"olcu","es":["elektrik dipol momenti","dipol momenti","electric dipole moment","μ"],"tanim":["Molekülün yük dağılımının asimetrisini gösteren ölçüdür (μ); birimi C·m ya da debye (D).","Kitapta tipik değerler H₂O için 1,85 D, CO₂ için 0'dır.","IR soğurma için μ'nun kendisi değil, titreşimle değişimi (∂μ/∂Q ≠ 0) belirleyicidir."],"tanim_en":"The electric dipole moment is a measure of the asymmetry of a molecule's charge distribution, and its change during vibration determines whether the molecule absorbs infrared radiation.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":["stokes"]}},{"id":"wavelength","tr":"Dalga boyu","en":"wavelength","kisa":"λ","tur":"olcu","es":["ışık dalga boyu","λ"],"tanim":["Dalganın ardışık iki tepesi arasındaki uzaklıktır (λ; µm, nm).","Frekansla ters orantılıdır (λν = c); foton enerjisi E = hc/λ olduğundan kısa dalga boyu yüksek enerji demektir.","Sıcak cisim kısa, soğuk cisim uzun dalga boyunda yayar: Güneş ≈ 0,5 µm'de, Dünya ≈ 10 µm'de en güçlüdür. Kitapta λ aynı zamanda iklim duyarlılığı parametresi (≈ 0,8 K/(W m⁻²)) için de kullanılır."],"tanim_en":"Wavelength is the distance between successive crests of a wave, inversely proportional to frequency, so that shorter wavelength corresponds to higher photon energy.","bag":{"kavram":["ir-aktif","koschmieder","beer-lambert"],"soru":["S15","S23","S24"],"hesap":["zorlama","fotoliz"]}},{"id":"bending-mode","tr":"Bükülme kipi","en":"bending mode","kisa":"ν₂","tur":"surec","es":["bükülme","açısal titreşim","bükülme titreşimi","bükülme modu","bending vibration"],"tanim":["Bağ açısının değiştiği titreşim kipidir (ν₂).","CO₂'de bükülme sırasında dipol oluşur ve kip IR aktiftir; 15 µm bandını verir.","15 µm Dünya ışımasının tepesine (≈ 10 µm) yakın olduğundan sera etkisinde en önemli kip budur."],"tanim_en":"The bending mode is the vibration in which the bond angle oscillates, and in CO₂ it is infrared-active and produces the strong 15 µm absorption band.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"selection-rule","tr":"Seçim kuralı","en":"selection rule","kisa":"","tur":"yontem","es":["seçilim kuralı","kuantum seçim kuralı","selection rules"],"tanim":["Bir geçişin hangi koşullarda olabileceğini belirleyen kuantum kuralıdır.","IR soğurma için kural şudur: foton enerjisi bir titreşim ya da dönme geçişine eşit olmalı ve o titreşim elektrik dipol momentini değiştirmelidir.","Harmonik titreşici için ⟨v'|Q|v⟩ yalnız v' = v ± 1 için sıfırdan farklıdır; bu yüzden şiddet (∂μ/∂Q)² ile orantılı olur."],"tanim_en":"A selection rule is a quantum-mechanical condition stating which transitions are allowed, and for infrared absorption it requires the vibration to change the molecule's electric dipole moment.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"wiens-displacement-law","tr":"Wien yasası","en":"Wien's displacement law","kisa":"λ_max","tur":"yontem","es":["Wien kayma yasası","Wien yer değiştirme yasası","Wien displacement law","tepe dalga boyu"],"tanim":["Siyah cisim gibi ışıyan bir cismin en şiddetli yaydığı dalga boyu, mutlak sıcaklıkla ters orantılıdır.","λ_max = b/T; b ≈ 2898 µm·K, T kelvin cinsinden, λ_max µm cinsinden. Sıcak cisim kısa, soğuk cisim uzun dalga boyunda tepe verir.","Güneşin kısa dalga (tepe ≈ 0,5 µm), Dünyanın uzun dalga (tepe ≈ 10 µm) ışımasını açıklar; böylece sera gazı molekülleri yalnız Dünya ışınımını tutar."],"tanim_en":"Wien's displacement law states that the wavelength of peak blackbody emission is inversely proportional to the absolute temperature of the emitter.","bag":{"kavram":["ir-aktif","stefan-boltzmann"],"soru":[],"hesap":["etkin-sicaklik"]}},{"id":"unit-watt-per-square-meter","tr":"Watt bölü metrekare","en":"watt per square metre","kisa":"W/m²","tur":"birim","es":["W m⁻²","W/m2","watt per square meter"],"tanim":["Birim yüzeyden birim zamanda geçen enerjiyi (güç akısı) ölçen SI türetilmiş birimidir: 1 W/m² = 1 J s⁻¹ m⁻².","Işınım akısı, ışınımsal zorlama ve güneş sabiti bu birimle verilir; kitapta S₀ = 1361 W/m², σ = 5,67 × 10⁻⁸ W m⁻² K⁻⁴ içinde geçer.","Atmosfer enerji bütçesini (soğurulan güneş, giden uzun dalga, sera etkisi ≈ 150 W/m²) karşılaştırmak için ortak ölçü sağlar."],"tanim_en":"The watt per square metre is the SI unit of power flux, equal to one joule of energy passing through one square metre of surface each second.","bag":{"kavram":["isinim-dengesi","zorlama","stefan-boltzmann"],"soru":["S6","S8","S9","S10"],"hesap":[]}},{"id":"brightness-temperature","tr":"Parlaklık sıcaklığı","en":"brightness temperature","kisa":"","tur":"kavram","es":["radiance temperature","equivalent blackbody temperature","eşdeğer siyah cisim sıcaklığı"],"tanim":["Uydunun belirli bir dalga boyunda ölçtüğü ışımayı veren siyah cismin sıcaklığıdır.","Ölçülen ışıma Planck yasasına ters uygulanarak kelvin cinsinden hesaplanır; yüzeyin yayıcılığı 1 değilse gerçek sıcaklıktan düşük çıkar.","Kızılötesi uydu görüntülerinde bulut tepesi ve yüzey sıcaklığını kestirmek için kullanılır; etkin sıcaklıktan (bütün tayf, gezegen ortalaması) farklıdır."],"tanim_en":"Brightness temperature is the temperature of a blackbody that would emit the same radiance as the observed source at a given wavelength.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"insolation","tr":"Güneşlenme","en":"insolation","kisa":"","tur":"kavram","es":["gelen güneş ışınımı","incoming solar radiation","güneş ışınımı girdisi"],"tanim":["Gelen güneş ışınımı; birim yatay yüzeye ulaşan güneş akısıdır.","W/m² cinsinden verilir; küresel ve yıllık ortalama S₀/4 ≈ 340 W/m² olur (1361 / 4).","Dünya enerji bütçesinin girdisidir; albedo ile çarpılıp (1−A) soğurulan kısmı bulunur. 'Insulation' (yalıtım) ile karıştırılmamalıdır."],"tanim_en":"Insolation is the rate at which solar radiation arrives at a unit horizontal surface at a given location or on average over the globe.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"shortwave-radiation","tr":"Kısa dalga ışınım","en":"shortwave radiation","kisa":"SW","tur":"kavram","es":["güneş ışınımı","kısa dalga","kısa dalga ışınımı","solar radiation","SW"],"tanim":["Güneşten gelen ve yaklaşık 0,2–4 µm aralığındaki ışınımdır: morötesi, görünür ve yakın kızılötesi.","Albedo ve aerosol saçılması bu ışınımı yansıtır ya da geri saçar; yer ve atmosfer onun geri kalanını soğurur.","Kitapta bulutların kısa dalga etkisi ΔF_SW = −S̄ ΔA ile hesaplanır; S̄ = S₀/4 ≈ 340 W/m². Sera gazı molekülleri bu ışınımı büyük ölçüde geçirir."],"tanim_en":"Shortwave radiation is the radiant energy from the Sun, mostly at wavelengths of about 0.2 to 4 µm, covering ultraviolet, visible and near-infrared light.","bag":{"kavram":["isinim-dengesi"],"soru":["S8","S10","S12","S24","S30","S33"],"hesap":[]}},{"id":"top-of-the-atmosphere","tr":"Atmosferin üst sınırı","en":"top of the atmosphere","kisa":"","tur":"kavram","es":["TOA","atmosferin tepesi","üst sınır","atmosfer üst sınırı"],"tanim":["Işınım bütçesinin hesaplandığı hayali üst sınırdır (TOA); atmosferin uzayla buluştuğu yüzey olarak alınır.","Uydular burada gelen güneş akısını ve giden uzun dalga akısını (OLR) ölçer; uzun dönemde net akı ≈ 0 olmalıdır.","Enerji dengesi ve ışınımsal zorlama bu düzeyde tanımlanır; tropopoz (troposferin tepesi) ile karıştırılmamalıdır."],"tanim_en":"The top of the atmosphere is the upper boundary at which the radiation budget is evaluated, where incoming solar radiation and outgoing longwave radiation are measured by satellites.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"outgoing-longwave-radiation","tr":"Uzaya giden uzun dalga ışınım","en":"outgoing longwave radiation","kisa":"OLR","tur":"olcu","es":["giden uzun dalga akı","uzaya giden IR","uzun dalga ışıma","giden uzun dalga akısı","uzaya giden uzun dalga boylu ışınım","uzaya giden uzun dalga ışınımı"],"tanim":["Atmosferin üst sınırından uzaya çıkan uzun dalga (kızılötesi) ışınım akısıdır.","W/m² cinsindendir; dengede soğurulan güneşe eşittir: OLR = S₀(1−A)/4 ≈ 238–240 W/m² ve OLR = σTₑ⁴.","Yüzeyin yaydığı ışınım (σT_s⁴ ≈ 390 W/m²) değildir; aradaki fark G = σT_s⁴ − OLR ≈ 150 W/m² sera etkisinin akı ölçüsüdür."],"tanim_en":"Outgoing longwave radiation is the flux of thermal infrared radiation leaving the top of the atmosphere and escaping to space.","bag":{"kavram":["isinim-dengesi","sera-etkisi"],"soru":["S6","S10"],"hesap":["etkin-sicaklik"]}},{"id":"solar-constant","tr":"Güneş sabiti","en":"solar constant","kisa":"S₀","tur":"olcu","es":["S0","gelen güneş akısı","toplam güneş ışınımı","total solar irradiance","TSI","S₀"],"tanim":["Ortalama Güneş–Dünya uzaklığında, güneş ışınlarına dik birim alana atmosferin dışında gelen ışınım akısıdır.","Dünya için S₀ ≈ 1361 W/m² (Venüs için ≈ 2600); akı 1/d² ile azalır. Güneş etkinliğiyle binde bir düzeyinde değiştiği için 'sabit' tam sabit değildir.","Kitapta Tₑ = [S₀(1−A)/(4σ)]^¼ ile etkin sıcaklığı hesaplamanın girdisidir."],"tanim_en":"The solar constant is the solar radiative flux received at the mean Sun–Earth distance on a surface perpendicular to the Sun's rays, outside the atmosphere.","bag":{"kavram":["isinim-dengesi"],"soru":["S6","S8","S10"],"hesap":["etkin-sicaklik"]}},{"id":"sym-absorbed-solar-flux","tr":"Soğurulan güneş akısı","en":"absorbed solar radiation","kisa":"S₀(1−A)/4","tur":"olcu","es":["soğurulan güneş","S₀(1−A)/4","absorbed solar flux"],"tanim":["Yer ve atmosferin (bulut ve yüzey dahil) gelen güneş ışınımından soğurduğu kısımdır.","Kitapta küresel ortalama olarak S₀(1−A)/4 ile verilir; S₀ = 1361 W/m², A = 0,30 için ≈ 238 W/m².","Dengede uzaya giden uzun dalga ışınıma (OLR) eşittir; böylece etkin sıcaklık Tₑ ≈ 255 K bulunur ve sera etkisi G = σT_s⁴ − S₀(1−A)/4 olarak hesaplanır."],"tanim_en":"Absorbed solar radiation is the part of the incident solar radiation that is taken up by the atmosphere's constituent gas molecules, clouds, suspended material or the Earth's surface.","bag":{"kavram":["isinim-dengesi"],"soru":["S6","S8","S30"],"hesap":["etkin-sicaklik"]}},{"id":"parts-per-billion","tr":"Milyarda bir","en":"parts per billion","kisa":"ppb","tur":"birim","es":["ppb","ppbv","hacimce milyarda bir"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻⁹ (mol/mol). Türkçe 'milyar' = İngilizce 'billion' (10⁹).","1 ppb = 10⁻⁹ ve 1 ppm = 1000 ppb. Kütle derişimine geçiş C = χ·M/24,45 (C: µg/m³, χ: ppb, M: g/mol).","Yerdeki ozon, NO₂ ve CH₄ gibi iz gazların derişimi bu birimle verilir; oran olduğu için basınç ve sıcaklıkla değişmez."],"tanim_en":"Parts per billion (ppb) is a unit of mixing ratio equal to one part in 10⁹, expressed as a mole fraction (mol/mol).","bag":{"kavram":["karisim-orani","kutle-derisimi"],"soru":["S1","S2","S44"],"hesap":["ppb-ugm3","ugm3-ppb"]}},{"id":"parts-per-million","tr":"Milyonda bir","en":"parts per million","kisa":"ppm","tur":"birim","es":["ppmv","hacimce milyonda bir","parts per million by volume"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻⁶ (mol/mol). Gazlarda ppmv (hacimce) de yazılır; ideal gazda mol payı hacim payına eşit olduğu için ikisi aynıdır.","Kuru havada CO₂ ≈ 420 ppm, stratosferde O₃ ≈ 8 ppm. Sudaki ppm çoğunlukla kütlecedir (mg/kg); bağlama bak.","Oran olduğu için P ve T değişse de sabit kalır; ppm ↔ mg/m³ dönüşümü ppb ↔ µg/m³ ile aynı formüldür."],"tanim_en":"Parts per million (ppm) is a unit of mixing ratio equal to one part in 10⁶, expressed for gas as a mole (or volume) fraction.","bag":{"kavram":["karisim-orani","zorlama","temiz-yagmur"],"soru":["S1","S2","S3","S4","S9","S26"],"hesap":[]}},{"id":"parts-per-trillion","tr":"Trilyonda bir","en":"parts per trillion","kisa":"ppt","tur":"birim","es":["ppt","pptv","hacimce trilyonda bir"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻¹² (mol/mol). İngilizce 'trillion' = 10¹² = Türkçe 'trilyon'.","1 ppt = 10⁻¹² ve 1 ppb = 1000 ppt.","CFC'ler ve öteki halojenli gazlar bu düzeyde; örneğin CFC-12 yaklaşık 500 ppt düzeyinde bulunur."],"tanim_en":"Parts per trillion (ppt) is a unit of mixing ratio equal to one part in 10¹², expressed as a mole fraction (mol/mol).","bag":{"kavram":["karisim-orani"],"soru":[],"hesap":[]}},{"id":"carbon-dioxide","tr":"Karbon dioksit","en":"carbon dioxide","kisa":"CO₂","tur":"kavram","es":["CO2","karbondioksit","karbon dioksit gazı","carbonic acid gas","Karbondioksit","CO₂"],"tanim":["Doğrusal, simetrik üç atomlu molekül (CO₂); havada hacimce ≈ %0,042 (≈ 420 ppm) bulunur ve sera etkisinde büyük rol oynar.","Küresel ortalama karışım oranı 2023'te ≈ 420 ppm, sanayi öncesi ≈ 278 ppm; yüzeyde kısmi basıncı ≈ 42,5 Pa (420 ppm × 1013 hPa).","En önemli insan kaynaklı sera gazıdır; 15 µm bandında soğurur. OH ile tepkimez, okyanus ve biyosfer yavaşça alır; bu yüzden tek bir ömür değeri yoktur. Temiz yağmurun pH'ını ≈ 5,6'ya çeker."],"tanim_en":"Carbon dioxide (CO₂) is a well-mixed atmospheric gas, present at about 420 ppm, that absorbs infrared radiation and plays a central role in the greenhouse effect.","bag":{"kavram":["karisim-orani","kutle-derisimi","atmosfer-kutlesi"],"soru":["S3","S4","S5","S9","S13","S18"],"hesap":["zorlama","ph-temiz"]}},{"id":"nitrous-oxide","tr":"Diazot monoksit","en":"nitrous oxide","kisa":"N₂O","tur":"kavram","es":["N2O","azot protoksit","dinitrogen monoxide","güldürücü gaz","N₂O"],"tanim":["Formülü N₂O olan, kararlı ve IR aktif (dipol değişimi olan) bir sera gazıdır. NO ve NO₂ ile karıştırılmaz.","Küresel ortalama karışım oranı 2023'te ≈ 337 ppb (≈ 0,33 ppm), sanayi öncesi ≈ 270 ppb. Ömrü ≈ 110 yıl, GWP-100 değeri ≈ 273.","İyi karışmış gazdır; troposferde yutağı yoktur, stratosfere ulaşıp azot oksitlerin kaynağı olur."],"tanim_en":"Nitrous oxide (N₂O) is a long-lived, well-mixed greenhouse gas with a lifetime of about 110 years that is also a source of nitrogen oxides in the stratosphere.","bag":{"kavram":["karisim-orani","atmosfer-kutlesi","sera-etkisi"],"soru":["S5"],"hesap":[]}},{"id":"ozone","tr":"Ozon","en":"ozone","kisa":"O₃","tur":"kavram","es":["O3","trioksijen","stratospheric ozone","troposferik ozon","trioxygen","stratosferik ozon"],"tanim":["Üç oksijen atomlu (O₃) tepkimeye yatkın moleküldür; stratosferde UV'yi soğuran tabakayı, troposferde ise bir oksidan ve kirleticiyi oluşturur.","Toplam sütun ortalama ≈ 300 DU (1 DU = 2,69 × 10¹⁶ molekül/cm²). Yüzeyde arka plan ≈ 30–50 ppb; stratosferde karışım oranı ≈ 30–35 km'de en yüksek (≈ 8–10 ppm).","Stratosferde Chapman çevrimiyle üretilir ve katalitik döngülerle yok olur; troposferde NO₂ fotolizinden oluşur ve NO ile titrasyona uğrar. IR aktiftir (9,6 µm bandı)."],"tanim_en":"Ozone (O₃) is a reactive triatomic form of oxygen that absorbs ultraviolet radiation in the stratosphere and acts as an oxidant and pollutant near the surface.","bag":{"kavram":["karisim-orani","sayi-yogunlugu","sera-etkisi"],"soru":["S1","S5","S21","S32","S40","S41"],"hesap":["chapman-o","cfc-ozon","leighton"]}},{"id":"trace-gas","tr":"İz gaz","en":"trace gas","kisa":"","tur":"kavram","es":["eser gaz","eser gazlar","iz gazlar","trace gases"],"tanim":["Havanın çok küçük bir kesrini oluşturan gaz. N₂ (%78), O₂ (%21) ve Ar (%0,93) ana bileşendir, iz gaz değildir.","Karışım oranı ppm, ppb ya da ppt ile verilir; kitapta mol payı χ olarak ele alınır. Örneğin CO₂ ≈ 420 ppm, CH₄ ≈ 1,9 ppm, N₂O ≈ 0,33 ppm.","Miktarı küçük olsa da etkisi büyük olabilir: ozon bir iz gazdır ama UV'yi güçlü soğurur."],"tanim_en":"A trace gas is a gas present in the atmosphere in very small amounts, typically expressed in ppm, ppb or ppt, in contrast to the major constituents N₂, O₂ and Ar.","bag":{"kavram":["karisim-orani"],"soru":["S4","S5","S14","S38"],"hesap":[]}},{"id":"water-vapor","tr":"Su buharı","en":"water vapor","kisa":"H₂O","tur":"kavram","es":["su buharı gazı","water vapour","H₂O"],"tanim":["Gaz hâlindeki su. Bükük ve kalıcı dipolü olan, IR aktif bir moleküldür.","Havadaki miktarı sıcaklıkla belirlenir: doymuş buhar basıncı her 1 K'de ≈ %7 artar (Clausius–Clapeyron). Karışma oranı r (kg/kg) bir kütle oranıdır; iz gazların χ'si ise mol oranıdır.","En güçlü sera gazıdır, ama zorlama değil geri beslemedir: ısınma nemi artırır, nem ısınmayı pekiştirir (pozitif geri besleme)."],"tanim_en":"Water vapor is water in the gaseous phase; it is the strongest greenhouse gas, and its atmospheric amount is controlled by temperature, so it acts as a feedback rather than a forcing.","bag":{"kavram":["karisim-orani","sera-etkisi","geri-besleme"],"soru":["S5","S8","S9","S11","S12","S13"],"hesap":["clausius"]}},{"id":"partial-pressure","tr":"Kısmi basınç","en":"partial pressure","kisa":"p","tur":"olcu","es":["kısmi gaz basıncı","p_i","gaz kısmi basıncı","p_CO2","partial gas pressure"],"tanim":["Gaz karışımında bir bileşenin tek başına bütün hacmi doldursaydı yapacağı basınç. Toplam basınç, kısmi basınçların toplamıdır.","p_X = χ_X · P (Dalton) ve p_X = n_X k T; birimi Pa ya da hPa.","Karışım oranı χ'nin mol payı ile basınç payına eşit olduğunu gösterir; ayrıca çözünme dengesinde (Henry) ve su buharında kullanılır."],"tanim_en":"Partial pressure is the pressure that one gas in a mixture would exert if it alone occupied the whole volume at the same temperature.","bag":{"kavram":["karisim-orani","temiz-yagmur"],"soru":["S3","S26"],"hesap":["ph-temiz"]}},{"id":"volume-fraction","tr":"Hacim payı","en":"volume fraction","kisa":"","tur":"olcu","es":["hacim oranı","hacimce oran","ppmv"],"tanim":["Bir bileşenin hacminin toplam hacme oranı; boyutsuzdur ve yüzde ya da ppmv olarak yazılır.","İdeal gazda mol payı = hacim payı = basınç payıdır; bu yüzden gazlarda 'ppmv' ile 'ppm' aynı şeydir. Kuru hava: N₂ %78, O₂ %21, Ar %0,93.","Kitabın aerosol bölümünde hacim payı başka anlamda geçer: her modun parçacık hacmi, n·(4/3)πr³ ile µm³/cm³ cinsinden. Gaz karışım oranıyla karıştırma."],"tanim_en":"Volume fraction is the ratio of the volume of a component to the total volume of the mixture, which for an ideal gas equals its mole fraction.","bag":{"kavram":["karisim-orani"],"soru":["S15","S17"],"hesap":["sayi-yogunlugu"]}},{"id":"second-order-reaction","tr":"İkinci mertebe tepkime","en":"Second-order reaction","kisa":"","tur":"surec","es":["ikinci mertebe kinetik","bimoleküler tepkime","ikinci dereceden tepkime"],"tanim":["Tepkime hızının iki ayrı türün derişimlerinin çarpımıyla veya tek bir türün derişiminin karesiyle orantılı olduğu kimyasal tepkime.","Hız ifadesi hız = k[A][B] şeklinde olup ikinci mertebe hız sabitinin birimi cm³ molekül⁻¹ s⁻¹ veya L mol⁻¹ s⁻¹ olarak verilir.","Troposferde CH₄ + OH ve CO + OH gibi hidroksil radikalinin yönlendirdiği temel gaz fazı arınma döngülerinin kinetiğini açıklar."],"tanim_en":"A chemical reaction whose rate is proportional to the product of the concentrations of two reacting chemical species.","bag":{"kavram":["omur","arrhenius"],"soru":[],"hesap":[]}},{"id":"albedo","tr":"Albedo","en":"albedo","kisa":"A","tur":"olcu","es":["yansıtırlık","gezegen albedosu","planetary albedo"],"tanim":["Bir yüzeyin yansıttığı ışınımın o yüzeye gelen ışınıma oranıdır.","Boyutsuzdur ve 0–1 arasındadır; kitapta A ile gösterilir ve gezegen albedosu yansıyan kısa dalga payıdır. Dünya ≈ 0,30, Venüs ≈ 0,70, taze kar ≈ 0,8–0,9, okyanus ≈ 0,06.","Soğurulan güneş S₀(1−A)/4'ü belirler; bulut, buz ve aerosol albedoyu değiştirerek iklimi etkiler. Aerosolün tek saçılma albedosu (ω) farklı bir kavramdır."],"tanim_en":"Albedo is the ratio of the radiation reflected by a surface to the radiation incident upon it.","bag":{"kavram":["volkan-aerosol","aerosol-dogrudan","isinim-dengesi"],"soru":["S6","S8","S9","S10","S11","S12"],"hesap":["etkin-sicaklik","bulut-net","optik-derinlik","beer-kesit"]}},{"id":"latent-heat","tr":"Gizli ısı","en":"latent heat","kisa":"L_v","tur":"olcu","es":["yoğuşma gizli ısısı","buharlaşma entalpisi","enthalpy of vaporization","buharlaşma gizli ısısı","latent heat of vaporization","L_v"],"tanim":["Bir maddenin hâl (faz) değişimi sırasında sıcaklığı değiştirmeden alınan ya da salınan enerji. Meteorolojide önemli olan su buharı, sıvı ve buz arasındaki değişimlerdir.","Buharlaşma için L_v ≈ 2,5 × 10⁶ J/kg; 1 kg suyu buhara çevirmek için gereken enerjidir. Faz değişiminde entropi farkı s_v − s_l = L_v / T olarak yazılır.","Yoğuşan buhar çevre havaya enerji verir (doymuş adyabatik soğuma yavaşlar); L_v ayrıca Clausius–Clapeyron bağıntısında doymuş buhar basıncının sıcaklıkla artışını belirler."],"tanim_en":"Latent heat is the amount of energy released or absorbed during a change of state of a substance, such as the evaporation or condensation of water.","bag":{"kavram":["volkan-aerosol","clausius","lcl"],"soru":["S11"],"hesap":["lcl"]}}]};
